const OFFICIAL_PDF_FONT = "TH SarabunIT๙";
const OFFICIAL_PDF_FONT_ALIAS = "THSarabunIT๙";
// BNK School OS global PDF font policy: every current/future official document must
// render with the same pinned TH Sarabun IT๙ font files on every device.
// Do not fall back to a device-installed font: if the webfont cannot load, PDF/print is blocked.
const OFFICIAL_PDF_FONT_URLS = Object.freeze({
  regular: "https://raw.githubusercontent.com/mhc9/react-mhc9-erp/d8a9ae3dc05f58fbd6889eb9803e231f36abf03e/public/fonts/THSarabunIT%E0%B9%99.ttf",
  bold: "https://raw.githubusercontent.com/mhc9/react-mhc9-erp/d8a9ae3dc05f58fbd6889eb9803e231f36abf03e/public/fonts/THSarabunIT%E0%B9%99%20Bold.ttf",
  italic: "https://raw.githubusercontent.com/mhc9/react-mhc9-erp/d8a9ae3dc05f58fbd6889eb9803e231f36abf03e/public/fonts/THSarabunIT%E0%B9%99%20Italic.ttf",
  boldItalic: "https://raw.githubusercontent.com/mhc9/react-mhc9-erp/d8a9ae3dc05f58fbd6889eb9803e231f36abf03e/public/fonts/THSarabunIT%E0%B9%99%20BoldItalic.ttf",
});
function officialPdfFontFaceCss() {
  return `@font-face{font-family:"${OFFICIAL_PDF_FONT}";src:url("${OFFICIAL_PDF_FONT_URLS.regular}") format("truetype");font-style:normal;font-weight:400;font-display:block}
@font-face{font-family:"${OFFICIAL_PDF_FONT}";src:url("${OFFICIAL_PDF_FONT_URLS.bold}") format("truetype");font-style:normal;font-weight:700;font-display:block}
@font-face{font-family:"${OFFICIAL_PDF_FONT}";src:url("${OFFICIAL_PDF_FONT_URLS.italic}") format("truetype");font-style:italic;font-weight:400;font-display:block}
@font-face{font-family:"${OFFICIAL_PDF_FONT}";src:url("${OFFICIAL_PDF_FONT_URLS.boldItalic}") format("truetype");font-style:italic;font-weight:700;font-display:block}`;
}
function installOfficialPdfFontCss(targetDocument=document) {
  if (!targetDocument?.head) return;
  if (targetDocument.getElementById("bnk-official-pdf-font")) return;
  const style=targetDocument.createElement("style");
  style.id="bnk-official-pdf-font";
  style.textContent=officialPdfFontFaceCss();
  targetDocument.head.appendChild(style);
}
async function ensureOfficialPdfFont(size="16pt", targetDocument=document) {
  if (!targetDocument?.fonts) throw new Error("อุปกรณ์นี้ไม่รองรับการโหลดฟอนต์เอกสารมาตรฐาน TH Sarabun IT๙");
  installOfficialPdfFontCss(targetDocument);
  const fonts=targetDocument.fonts;
  await Promise.all([
    fonts.load(`400 ${size} "${OFFICIAL_PDF_FONT}"`),
    fonts.load(`700 ${size} "${OFFICIAL_PDF_FONT}"`),
    fonts.ready,
  ]);
  const ok=fonts.check(`400 ${size} "${OFFICIAL_PDF_FONT}"`) && fonts.check(`700 ${size} "${OFFICIAL_PDF_FONT}"`);
  if (!ok) throw new Error("โหลดฟอนต์ TH Sarabun IT๙ ไม่สำเร็จ จึงหยุดสร้างเอกสารเพื่อป้องกัน PDF ฟอนต์ผิด");
  return true;
}
installOfficialPdfFontCss(document);

// BNK v5.0.16 — adaptive responsive UI layer.
// Read-only data tables become mobile cards automatically. Editable/complex tables keep
// horizontal scrolling so inputs and official data structures are never distorted.
const BNK_RESPONSIVE_TABLE_EXCLUDES = [
  ".procurement-items-table", ".procurement-quotation-table", ".post-score-table",
  ".lesson-unit-table", ".lesson-sat-table", ".student-followup-pick-table"
];
function bnkTableIsOfficialPreview(table){
  let node=table;
  while(node && node!==document.body){
    const classes=String(node.className||"");
    if(/(?:^|\s)(?:a4-|.*-pdf-|pdf-|procurement-pack|procurement-control-register)/i.test(classes)) return true;
    node=node.parentElement;
  }
  return false;
}
function enhanceResponsiveTables(root=document){
  const scope=root?.querySelectorAll ? root : document;
  scope.querySelectorAll(".table-wrap > table.table").forEach(table=>{
    if(table.dataset.bnkResponsiveReady==="1" || bnkTableIsOfficialPreview(table)) return;
    table.dataset.bnkResponsiveReady="1";
    const wrap=table.closest(".table-wrap");
    const headings=[...table.querySelectorAll("thead th")].map(th=>th.textContent.trim());
    const rows=[...table.querySelectorAll("tbody tr")];
    const excluded=BNK_RESPONSIVE_TABLE_EXCLUDES.some(sel=>table.matches(sel));
    const interactive=!!table.querySelector("input,select,textarea,[contenteditable='true']");
    const complex=!headings.length || rows.some(row=>row.querySelector("[rowspan],[colspan]") || row.children.length!==headings.length);
    if(excluded || interactive || complex){
      table.classList.add("responsive-scroll-table");
      wrap?.classList.add("mobile-horizontal-table");
      return;
    }
    table.classList.add("responsive-card-table");
    wrap?.classList.add("mobile-card-table-wrap");
    rows.forEach(row=>[...row.children].forEach((cell,index)=>{
      cell.dataset.label=headings[index]||"";
    }));
  });
}
function setMobileSidebar(open){
  state.sidebarOpen=!!open;
  document.querySelector(".dashboard")?.classList.toggle("sidebar-open",state.sidebarOpen);
  document.body.classList.toggle("bnk-nav-open",state.sidebarOpen && window.matchMedia("(max-width: 1000px)").matches);
}
const responsiveUiObserver=new MutationObserver(mutations=>{
  if(!mutations.some(m=>m.addedNodes?.length)) return;
  requestAnimationFrame(()=>enhanceResponsiveTables(document));
});
responsiveUiObserver.observe(document.body,{childList:true,subtree:true});
window.addEventListener("resize",()=>{
  if(window.innerWidth>1000) document.body.classList.remove("bnk-nav-open");
  else if(state?.sidebarOpen) document.body.classList.add("bnk-nav-open");
});
document.addEventListener("keydown",event=>{
  if(event.key==="Escape" && state?.sidebarOpen) setMobileSidebar(false);
});

