async function lessonUsageUploadSignature(reportId,slot,blob,mime){const ext=mime==="image/png"?"png":mime==="image/webp"?"webp":"jpg",path=`lesson-plan-usage-signatures/${reportId}/${slot}/${crypto.randomUUID()}.${ext}`;const up=await supabase.storage.from("academic-submissions").upload(path,blob,{contentType:mime,upsert:false});if(up.error)throw up.error;return path;}
