function classroomResearchVersionHistoryModal(id){const r=classroomResearchReportById(id),versions=classroomResearchVersionsFor(id);if(!r)return;const modal=document.createElement("div");modal.className="modal-backdrop";modal.innerHTML=`<div class="modal"><div class="modal-head"><div><h3>ประวัติ Version งานวิจัย</h3><p>${escapeHtml(r.title)}</p></div><button class="modal-close">×</button></div><div class="research-version-list">${versions.length?versions.map(v=>{const snap=v.snapshot||{};return `<article class="research-version-row"><div><strong>Version ${v.document_version}</strong><span>${escapeHtml(snap.title||r.title)} · ส่ง ${escapeHtml(thaiDateTimeDocument(v.submitted_at))}</span></div>${v.research_storage_path?`<button class="btn btn-ghost btn-sm" data-research-version-file="${v.id}">เปิด PDF ฉบับนี้</button>`:`<span class="pill muted">สร้างในระบบ</span>`}</article>`;}).join(""):`<div class="empty"><strong>ยังไม่มี Version ที่ส่ง</strong></div>`}</div><div class="modal-actions"><button class="btn btn-primary modal-cancel">ปิด</button></div></div>`;document.body.appendChild(modal);const close=()=>modal.remove();modal.querySelector(".modal-close").onclick=close;modal.querySelector(".modal-cancel").onclick=close;modal.querySelectorAll("[data-research-version-file]").forEach(b=>b.onclick=()=>classroomResearchOpenVersionOriginal(id,b.dataset.researchVersionFile));}
async function classroomResearchOpenVersionOriginal(reportId,versionId){const v=classroomResearchVersionsFor(reportId).find(x=>x.id===versionId);if(!v?.research_storage_path)return toast("ไม่มี PDF ต้นฉบับ","Version นี้สร้างเอกสารในระบบ","error");const dl=await supabase.storage.from(v.research_bucket||"academic-submissions").download(v.research_storage_path);if(dl.error)return toast("เปิด PDF ไม่สำเร็จ",dl.error.message,"error");const url=URL.createObjectURL(dl.data);window.open(url,"_blank","noopener,noreferrer");setTimeout(()=>URL.revokeObjectURL(url),300000);}
async function classroomResearchOpenOriginal(id){const r=classroomResearchReportById(id);if(!r?.research_storage_path)return toast("ไม่มี PDF ต้นฉบับ","รายการนี้สร้างในระบบหรือยังไม่ได้แนบไฟล์","error");const dl=await supabase.storage.from(r.research_bucket||"academic-submissions").download(r.research_storage_path);if(dl.error)return toast("เปิด PDF ไม่สำเร็จ",dl.error.message,"error");const url=URL.createObjectURL(dl.data);window.open(url,"_blank","noopener,noreferrer");setTimeout(()=>URL.revokeObjectURL(url),300000);}
