function learnerActivityResultFor(student,act){const raw=student.activity_results?.[act.id]||{},n=Number(act.session_count||0);const attendance=Array.isArray(raw.attendance)?raw.attendance.slice(0,n).map(Boolean):[];while(attendance.length<n)attendance.push(false);return {attendance,learning_pass:typeof raw.learning_pass==="boolean"?raw.learning_pass:null,manual_result:["pass","fail"].includes(raw.manual_result)?raw.manual_result:null,note:raw.note||""};}
