function clubActivityAttendanceModal(id){const r=clubActivityReportById(id);if(!r||!clubActivityCanEdit(r))return;const members=clubActivityMembersFor(id);if(!members.length)return toast("ยังไม่มีสมาชิก","เพิ่มสมาชิกชุมนุมก่อนบันทึกเวลา","error");const count=Number(r.session_count||0),chunks=[];for(let i=0;i<count;i+=20)chunks.push([i,Math.min(i+20,count)]);let chunkIndex=0;const draft=new Map(members.map(m=>[m.student_id,{attendance:clubActivityNormalizeAttendance(m,count),objective_pass:m.objective_pass===true}])),modal=document.createElement("div");modal.className="modal-backdrop";modal.innerHTML=`<div class="modal modal-wide"><div class="modal-head"><div><h3>เวลาเข้าร่วมและผลการประเมิน</h3><p>${escapeHtml(r.club_name)} · เกณฑ์เวลา ${Number(r.attendance_threshold)}% · ผ่านจุดประสงค์ครบทุกข้อ</p></div><button class="modal-close">×</button></div><div class="post-score-tools"><div><select class="select" id="club-att-range">${chunks.map((x,i)=>`<option value="${i}">${x[0]+1}-${x[1]} จาก ${count} ${escapeHtml(r.tracking_unit||"ครั้ง")}</option>`).join("")}</select></div><div><button type="button" class="btn btn-ghost" id="club-att-all-present">✓ ช่วงนี้มาทั้งหมด</button><button type="button" class="btn btn-ghost" id="club-att-all-absent">– ช่วงนี้ขาดทั้งหมด</button></div></div><div class="table-wrap" style="max-height:55vh"><table class="table club-att-table"><thead id="club-att-head"></thead><tbody id="club-att-body"></tbody></table></div><div class="modal-actions"><button class="btn btn-ghost modal-cancel">ยกเลิก</button><button class="btn btn-primary" id="club-att-save">บันทึกเวลาและผล</button></div></div>`;document.body.appendChild(modal);const head=modal.querySelector("#club-att-head"),body=modal.querySelector("#club-att-body"),calc=(m)=>{const d=draft.get(m.student_id),att=d.attendance.filter(Boolean).length,pct=count?att*100/count:0,pass=d.objective_pass&&pct>=Number(r.attendance_threshold);return {att,pct,pass};},render=()=>{const [start,end]=chunks[chunkIndex];head.innerHTML=`<tr><th style="min-width:40px">#</th><th style="min-width:145px">ชื่อ-สกุล</th>${Array.from({length:end-start},(_,k)=>`<th>${start+k+1}</th>`).join("")}<th>รวม</th><th>ผ่านจุดประสงค์</th><th>ผล</th></tr>`;body.innerHTML=members.map((m,ri)=>{const d=draft.get(m.student_id),x=calc(m);return `<tr><td>${ri+1}</td><td class="post-score-name">${escapeHtml(m.student_name)}<br><small>${escapeHtml(m.class_label||"")}</small></td>${Array.from({length:end-start},(_,k)=>{const i=start+k;return `<td><button type="button" class="club-att-cell ${d.attendance[i]?"present":"absent"}" data-club-att-student="${m.student_id}" data-club-att-index="${i}">${d.attendance[i]?"✓":"–"}</button></td>`;}).join("")}<td>${x.att}/${count}<br><small>${x.pct.toFixed(1)}%</small></td><td><input type="checkbox" data-club-objective="${m.student_id}" ${d.objective_pass?"checked":""}></td><td><strong>${x.pass?"ผ":"มผ"}</strong></td></tr>`;}).join("");body.querySelectorAll("[data-club-att-student]").forEach(b=>b.onclick=()=>{const d=draft.get(b.dataset.clubAttStudent),i=Number(b.dataset.clubAttIndex);d.attendance[i]=!d.attendance[i];render();});body.querySelectorAll("[data-club-objective]").forEach(ch=>ch.onchange=()=>{draft.get(ch.dataset.clubObjective).objective_pass=ch.checked;render();});};modal.querySelector("#club-att-range").onchange=e=>{chunkIndex=Number(e.currentTarget.value);render();};modal.querySelector("#club-att-all-present").onclick=()=>{const [start,end]=chunks[chunkIndex];draft.forEach(d=>{for(let i=start;i<end;i++)d.attendance[i]=true;});render();};modal.querySelector("#club-att-all-absent").onclick=()=>{const [start,end]=chunks[chunkIndex];draft.forEach(d=>{for(let i=start;i<end;i++)d.attendance[i]=false;});render();};const close=()=>modal.remove();modal.querySelector(".modal-close").onclick=close;modal.querySelector(".modal-cancel").onclick=close;modal.querySelector("#club-att-save").onclick=async e=>{buttonLoading(e.currentTarget,true,"กำลังบันทึก...");try{const rows=members.map(m=>({student_id:m.student_id,attendance:draft.get(m.student_id).attendance,objective_pass:draft.get(m.student_id).objective_pass}));const {error}=await supabase.rpc("save_club_activity_members",{p_report_id:id,p_members:rows});if(error)throw error;close();toast("บันทึกเวลาและผลแล้ว",`${rows.length} คน`,"success");await loadAcademicSubmissionWorkspace();await renderDashboard();}catch(err){toast("บันทึกไม่สำเร็จ",err.message||String(err),"error");}finally{buttonLoading(e.currentTarget,false);}};render();}
