function toDatetimeLocal(value){if(!value)return "";const d=new Date(value),pad=n=>String(n).padStart(2,"0");return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;}
function academicSubmissionDeadlineSource(systemCode=postLessonSystemCode()){
  if(systemCode===lessonPlanUsageSystemCode())return state.academicLessonPlanUsageDeadline;
  if(systemCode===learningMediaSystemCode())return state.academicLearningMediaDeadline;
  if(systemCode===classroomResearchSystemCode())return state.academicClassroomResearchDeadline;
  return state.academicSubmissionDeadline;
}
function academicSubmissionSystemTitle(systemCode=postLessonSystemCode()){
  if(systemCode===postLessonSystemCode())return "บันทึกผลหลังการจัดการเรียนรู้";
  return ACADEMIC_SUBMISSION_SYSTEMS.find(x=>x.code===systemCode)?.title||"ระบบส่งงานวิชาการ";
}
function academicSubmissionDeadlineModal(systemCode=postLessonSystemCode()){
  if(!academicSubmissionCanConfigureUi())return;
  const source=academicSubmissionDeadlineSource(systemCode);
  const d=source||{},p=academicSubmissionPeriod(),modal=document.createElement("div");
  const weeklyStart=academicSubmissionThaiDateInput(d.opens_at),weeklyDue=academicSubmissionThaiDateInput(d.due_at);
  modal.className="modal-backdrop";
  modal.innerHTML=`<div class="modal"><div class="modal-head"><div><h3>กำหนดช่วงเวลารับส่งงาน</h3><p>${escapeHtml(academicSubmissionSystemTitle(systemCode))} · ปีการศึกษา ${p.academicYear} ภาคเรียนที่ ${p.semester}</p></div><button class="modal-close">×</button></div><form id="academic-deadline-form" class="form-grid"><label class="post-deadline-switch"><input type="checkbox" name="enabled" ${d.deadline_enabled?"checked":""}><span><strong>กำหนดวันเปิดรับและวันปิดรับ</strong><small>ปิดสวิตช์ = ครูส่งได้ตลอดเวลา</small></span></label><div class="form-row"><div class="field"><label>วันเปิดรับ</label><input class="input" type="date" name="weekly_start" value="${weeklyStart}"></div><div class="field"><label>วันกำหนดส่ง / ปิดรับ</label><input class="input" type="date" name="weekly_due" value="${weeklyDue}"></div></div><div class="helper">ส่วนนี้กำหนดเฉพาะช่วงเปิด–ปิดรับของ ${escapeHtml(academicSubmissionSystemTitle(systemCode))} ไม่เปลี่ยนข้อมูลปีการศึกษา/ภาคเรียนหรือรูปแบบเอกสารที่ครูกรอกไว้</div></form><div class="modal-actions"><button class="btn btn-ghost modal-cancel">ยกเลิก</button><button class="btn btn-primary" id="academic-deadline-save">บันทึกกำหนดส่ง</button></div></div>`;
  document.body.appendChild(modal);const close=()=>modal.remove(),form=modal.querySelector("#academic-deadline-form");modal.querySelector(".modal-close").onclick=close;modal.querySelector(".modal-cancel").onclick=close;
  modal.querySelector("#academic-deadline-save").onclick=async e=>{const fd=new FormData(form),enabled=fd.get("enabled")==="on";let opens=null,due=null;if(enabled){const st=String(fd.get("weekly_start")||""),du=String(fd.get("weekly_due")||"");if(!st||!du)return toast("กรุณาเลือกวันที่","เมื่อเปิดกำหนดส่ง ต้องมีวันเปิดรับและวันปิดรับ","error");if(du<st)return toast("วันที่ไม่ถูกต้อง","วันกำหนดส่งต้องไม่อยู่ก่อนวันเปิดรับ","error");opens=academicSubmissionDayBoundaryIso(st,false);due=academicSubmissionDayBoundaryIso(du,true);}buttonLoading(e.currentTarget,true,"กำลังบันทึก...");const {error}=await supabase.rpc("set_academic_submission_deadline",{p_system_code:systemCode,p_academic_year:String(p.academicYear),p_semester:p.semester,p_enabled:enabled,p_period_type:"weekly",p_opens_at:opens,p_due_at:due});buttonLoading(e.currentTarget,false);if(error)return toast("บันทึกกำหนดส่งไม่สำเร็จ",error.message,"error");close();toast("บันทึกกำหนดส่งแล้ว",enabled?"ระบบจะเปิดและปิดรับตามวันที่ที่กำหนด":"ครูสามารถส่งงานได้ตลอดเวลา","success");await loadAcademicSubmissionWorkspace();await renderDashboard();};
}

async function postLessonDelete(id){
  const r=postLessonReportById(id);if(!r||!academicSubmissionCanDeleteRecord(r))return;
  secureDeleteModal({title:"ลบบันทึกผลหลังการจัดการเรียนรู้",description:`${r.subject_name||""} ${r.class_label||""} · ${r.unit_title||""}`,warning:"ข้อมูลพฤติกรรม ลายเซ็น และรายการที่ผูกกับบันทึกนี้จะถูกลบตามไปด้วย หากเป็นครูผู้จัดทำต้องยืนยันรหัสผ่านของตนเองก่อนลบ",action:async client=>{const files=(state.academicPostLessonSignatures||[]).filter(x=>x.report_id===id&&x.storage_path);for(const x of files){const rm=await client.storage.from(x.bucket||"academic-submissions").remove([x.storage_path]);if(rm.error)throw rm.error;}const res=await client.rpc("delete_post_lesson_report",{p_report_id:id});if(res.error)throw res.error;},afterDelete:async()=>{toast("ลบบันทึกแล้ว","ระบบบันทึกประวัติการลบไว้ใน Audit Log","success");await loadAcademicSubmissionWorkspace();await renderDashboard();}});
}

async function postLessonSignatureAssets(r){
  const out={},slots=["teacher","academic_head","director"],direct=Object.fromEntries(slots.map(slot=>[slot,postLessonSignatureFor(r.id,slot)]));
  for(const slot of slots){const sig=direct[slot];if(sig){out[`${slot}Meta`]=sig;if(sig.method!=="paper"&&sig.storage_path){const dl=await supabase.storage.from(sig.bucket||"academic-submissions").download(sig.storage_path);if(!dl.error)out[slot]=await blobToDataUrl(dl.data);}}}
  const legacyIds=[];if(!direct.teacher&&r.teacher_signature_id)legacyIds.push(r.teacher_signature_id);if(!direct.academic_head&&r.reviewer_signature_id)legacyIds.push(r.reviewer_signature_id);
  if(legacyIds.length){const {data}=await supabase.from("signatures").select("*").in("id",legacyIds);for(const sig of data||[]){const url=await signatureDataUrl(sig);if(!direct.teacher&&sig.id===r.teacher_signature_id)out.teacher=url;if(!direct.academic_head&&sig.id===r.reviewer_signature_id)out.academic_head=url;}}
  return out;
}

function postLessonPdfSignBlock(title,name,position,img){return `<div class="pl-sign"><div class="pl-sign-space">${img?`<img src="${img}" alt="ลายเซ็น">`:""}</div><div class="pl-sign-line">ลงชื่อ ........................................................</div><div>( ${escapeHtml(name||"........................................")} )</div>${position?`<div class="pl-sign-position">${escapeHtml(position)}</div>`:`<div class="pl-sign-position">${escapeHtml(title)}</div>`}</div>`;}
function postLessonPdfSection(title,text){return `<section class="pl-section"><h3>${escapeHtml(title)}</h3><p>${escapeHtml(text||"-").replace(/\n/g,"<br>")}</p></section>`;}
function postLessonBehaviorPageRows(rows){return `<table class="pl-score-table"><thead><tr><th rowspan="2">ที่</th><th rowspan="2">ชื่อ–สกุล</th><th colspan="5">ระดับคะแนน</th><th rowspan="2">รวม<br>15</th><th rowspan="2">คุณภาพ</th></tr><tr><th>แสดง<br>ความคิดเห็น</th><th>รับฟัง<br>ผู้อื่น</th><th>ทำงานตาม<br>มอบหมาย</th><th>มีน้ำใจ</th><th>ร่วมปรับปรุง<br>ผลงานกลุ่ม</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.student_number||""}</td><td class="name">${escapeHtml(x.student_name)}</td><td>${x.expression_score}</td><td>${x.listening_score}</td><td>${x.assigned_work_score}</td><td>${x.helpfulness_score}</td><td>${x.group_improvement_score}</td><td><strong>${x.total_score}</strong></td><td>${postLessonQuality(x.total_score)}</td></tr>`).join("")}</tbody></table>`;}

async function postLessonPdfHtml(r,scores){
  const [logo,sigs]=await Promise.all([schoolLogoDataUrl(),postLessonSignatureAssets(r)]),unit=postLessonScopePdfText(r),wf=academicSubmissionWorkflowSettings();
  const headName=sigs.academic_headMeta?.signer_name||r.reviewer_name||wf.academic_head_name||"........................................",headPosition=sigs.academic_headMeta?.signer_position||r.reviewer_position||wf.academic_head_position||"หัวหน้ากลุ่มงานบริหารงานวิชาการ";
  const directorName=sigs.directorMeta?.signer_name||wf.director_name||"........................................",directorPosition=sigs.directorMeta?.signer_position||wf.director_position||"ผู้อำนวยการสถานศึกษา";
  const pages=[];
  pages.push(`<article class="post-lesson-pdf-page pl-cover"><div class="pl-page-inner">${logo?`<img class="pl-logo" src="${logo}" alt="ตราโรงเรียน">`:""}<div class="pl-cover-spacer"></div><h1>แบบบันทึกหลังแผนการจัดการเรียนรู้</h1><h2>${escapeHtml(r.subject_name)}</h2><h3>${escapeHtml(r.class_label)}</h3><div class="pl-cover-meta"><span>ผู้รับผิดชอบกิจกรรม</span><strong>${escapeHtml(r.teacher_name)}</strong><span>${escapeHtml(r.teacher_position||"ครูผู้สอน")}</span><span>ปีการศึกษา ${escapeHtml(r.academic_year)} ภาคเรียนที่ ${r.semester}</span><span>รูปแบบบันทึก: ${escapeHtml(postLessonScopeLabel(r))}</span></div><footer><strong>${escapeHtml(schoolName())}</strong><span>${escapeHtml(schoolAddress())}</span><span>${escapeHtml(educationOffice())}</span></footer></div></article>`);
  pages.push(`<article class="post-lesson-pdf-page"><div class="pl-page-inner pl-page-content"><header class="pl-doc-head"><h1>แบบบันทึกหลังแผนการจัดการเรียนรู้</h1><div>${escapeHtml(r.subject_name)} · ${escapeHtml(r.class_label)} · ปีการศึกษา ${escapeHtml(r.academic_year)}</div><strong>${escapeHtml(unit)}</strong></header>${postLessonPdfSection("ด้านความรู้",r.knowledge_text)}${postLessonPdfSection("ด้านสมรรถนะสำคัญของผู้เรียน",r.competency_text)}${postLessonPdfSection("ด้านคุณลักษณะอันพึงประสงค์",r.desirable_attributes_text)}${postLessonPdfSection(r.subject_specific_title||"ด้านความสามารถเฉพาะรายวิชา",r.subject_specific_text)}</div></article>`);
  pages.push(`<article class="post-lesson-pdf-page"><div class="pl-page-inner pl-page-content">${postLessonPdfSection("ด้านอื่น ๆ (พฤติกรรมเด่นหรือพฤติกรรมที่มีปัญหาของนักเรียนเป็นรายบุคคล (ถ้ามี))",r.other_notes)}${postLessonPdfSection("ปัญหา/อุปสรรค",r.problems_text)}${postLessonPdfSection("แนวทางการแก้ไข",r.solutions_text)}<div class="pl-teacher-sign">${postLessonPdfSignBlock("ผู้บันทึก",r.teacher_name,r.teacher_position,sigs.teacher)}</div></div></article>`);
  pages.push(`<article class="post-lesson-pdf-page"><div class="pl-page-inner pl-approval-page"><header class="pl-doc-head"><h1>การตรวจและรับรองงานวิชาการ</h1><div>${escapeHtml(r.subject_name)} · ${escapeHtml(r.class_label)} · ${escapeHtml(unit)}</div></header><section class="pl-review"><h3>ความเห็นของหัวหน้างานวิชาการ</h3><div class="pl-review-lines"><strong>ข้อเสนอแนะ</strong><p>${escapeHtml(r.reviewer_comment||"").replace(/\n/g,"<br>")||"....................................................................................................................................................................................<br>....................................................................................................................................................................................<br>...................................................................................................................................................................................."}</p></div>${postLessonPdfSignBlock("หัวหน้างานวิชาการ",headName,headPosition,sigs.academic_head)}</section><section class="pl-executive-approval"><h3>การรับรองของผู้บริหารสถานศึกษา</h3><div class="pl-executive-grid">${postLessonPdfSignBlock("ผู้อำนวยการ",directorName,directorPosition,sigs.director)}</div></section></div></article>`);
  if(r.include_behavior_assessment&&scores.length){const chunks=[];for(let i=0;i<scores.length;i+=26)chunks.push(scores.slice(i,i+26));chunks.forEach((chunk,i)=>pages.push(`<article class="post-lesson-pdf-page"><div class="pl-page-inner pl-score-page"><header class="pl-doc-head"><h1>แบบสังเกตพฤติกรรมการทำงานกลุ่ม</h1><div>${escapeHtml(r.subject_name)} · ${escapeHtml(r.class_label)} · ${escapeHtml(unit)}</div></header><p class="pl-instruction"><strong>คำชี้แจง :</strong> ให้ผู้สอนสังเกตพฤติกรรมของนักเรียน แล้วบันทึกระดับคะแนนที่ตรงกับพฤติกรรม</p>${postLessonBehaviorPageRows(chunk)}${i===chunks.length-1?`<div class="pl-score-criteria"><strong>เกณฑ์ให้คะแนน</strong><span>ปฏิบัติหรือแสดงพฤติกรรมอย่างสม่ำเสมอ (100%) = 3 คะแนน · บ่อยครั้ง (70%) = 2 คะแนน · บางครั้ง (50%) = 1 คะแนน</span><strong>เกณฑ์การตัดสินคุณภาพ</strong><span>14–15 ดีมาก · 11–13 ดี · 8–10 พอใช้ · ต่ำกว่า 8 ปรับปรุง</span></div>`:""}</div></article>`));}
  return `<style>${postLessonPdfStyles()}</style><div class="post-lesson-pdf-root">${pages.join("")}</div>`;
}

function postLessonPdfStyles(){return `
  ${officialPdfFontFaceCss()}
  .post-lesson-pdf-root,.post-lesson-pdf-root *{font-family:"TH SarabunIT๙","THSarabunIT๙",serif!important;box-sizing:border-box}.post-lesson-pdf-root{position:fixed;left:-20000px;top:0;background:#fff;font-family:"TH SarabunIT๙","THSarabunIT๙",serif;color:#111}.post-lesson-pdf-page{width:210mm;height:297mm;background:#fff;box-sizing:border-box;overflow:hidden}.pl-page-inner{height:100%;box-sizing:border-box;padding:13mm 15mm;font-size:16pt;line-height:1.25}.pl-cover .pl-page-inner{display:flex;flex-direction:column;align-items:center;text-align:center}.pl-logo{width:28mm;height:28mm;object-fit:contain}.pl-cover-spacer{height:25mm}.pl-cover h1{font-size:27pt;margin:0 0 5mm}.pl-cover h2{font-size:22pt;margin:0 0 2mm}.pl-cover h3{font-size:20pt;margin:0}.pl-cover-meta{margin-top:24mm;display:flex;flex-direction:column;gap:2mm;font-size:18pt}.pl-cover-meta strong{font-size:21pt}.pl-cover footer{margin-top:auto;display:flex;flex-direction:column;font-size:15pt}.pl-doc-head{text-align:center;border-bottom:1px solid #555;padding-bottom:3mm;margin-bottom:4mm}.pl-doc-head h1{font-size:21pt;margin:0}.pl-doc-head div{font-size:15pt}.pl-doc-head strong{display:block;font-size:17pt;margin-top:1mm}.pl-section{margin:0 0 4mm}.pl-section h3{font-size:17pt;margin:0 0 1mm}.pl-section p{font-size:15.5pt;line-height:1.28;margin:0;text-align:justify;text-indent:12mm}.pl-teacher-sign{display:flex;justify-content:flex-end;margin-top:9mm}.pl-sign{width:92mm;text-align:center;font-size:15pt;line-height:1.2}.pl-sign>div:not(.pl-sign-space){white-space:nowrap}.pl-sign-space{height:16mm;position:relative}.pl-sign-space img{max-height:22mm;max-width:55mm;position:absolute;left:50%;bottom:-4mm;transform:translateX(-50%);object-fit:contain}.pl-review{margin-top:3mm}.pl-head-self-note{margin:18mm auto 10mm;max-width:145mm;text-align:center;font-size:15pt;line-height:1.45}.pl-head-self-note p{margin:3mm 0}.pl-executive-approval.self-head{margin-top:20mm}.post-lesson-workflow-note{display:block;margin-top:8px;max-width:760px;line-height:1.45}.post-lesson-role-tabs{display:flex;gap:10px;flex-wrap:wrap;margin:0 0 14px}.pl-review>h3,.pl-executive-approval>h3{text-align:center;font-size:18pt;margin:0 0 4mm}.pl-review-lines p{min-height:32mm;line-height:1.75;margin:2mm 0 5mm}.pl-review .pl-sign{margin-left:auto;margin-right:auto}.pl-approval-page{padding-top:15mm}.pl-executive-approval{margin-top:14mm;padding-top:7mm;border-top:1px solid #777}.pl-executive-grid{display:flex;justify-content:center;align-items:flex-start}.pl-executive-grid .pl-sign{width:92mm;margin-left:auto;margin-right:auto}.pl-score-page{padding:10mm 8mm}.pl-instruction{font-size:13pt;margin:2mm 0}.pl-score-table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:10.2pt;line-height:1.05}.pl-score-table th,.pl-score-table td{border:1px solid #222;padding:1.05mm .7mm;text-align:center;vertical-align:middle}.pl-score-table th:nth-child(1){width:8mm}.pl-score-table th:nth-child(2){width:55mm}.pl-score-table .name{text-align:left}.pl-score-criteria{margin-top:4mm;display:grid;grid-template-columns:32mm 1fr;gap:1mm 3mm;font-size:11.5pt}
`;}

function postLessonFitPdfPages(host){
  host.querySelectorAll(".post-lesson-pdf-page").forEach(page=>{
    const inner=page.querySelector(".pl-page-inner");if(!inner)return;
    inner.style.transform="none";inner.style.transformOrigin="top left";inner.style.width="100%";
    const scale=Math.min(1,page.clientWidth/Math.max(inner.scrollWidth,1),page.clientHeight/Math.max(inner.scrollHeight,1));
    const safe=Math.max(.76,Math.min(1,scale*.992));
    if(safe<.999){inner.style.width=`${100/safe}%`;inner.style.transform=`scale(${safe})`;}
  });
}

async function postLessonBuildPdfBlob(id){
  const r=postLessonReportById(id);if(!r)throw new Error("ไม่พบรายการ");const scores=postLessonScoresFor(id),host=document.createElement("div");host.innerHTML=await postLessonPdfHtml(r,scores);document.body.appendChild(host);const pages=[...host.querySelectorAll(".post-lesson-pdf-page")];
  try{await ensureOfficialPdfFont("16pt");postLessonFitPdfPages(host);await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));const pdf=new jsPDF({orientation:"portrait",unit:"mm",format:"a4",compress:true});for(let i=0;i<pages.length;i++){if(i)pdf.addPage("a4","portrait");const canvas=await html2canvas(pages[i],{scale:1.8,useCORS:true,backgroundColor:"#ffffff",logging:false});pdf.addImage(canvas.toDataURL("image/jpeg",0.92),"JPEG",0,0,210,297,undefined,"FAST");}return {blob:pdf.output("blob"),filename:`บันทึกหลังแผน_${r.subject_name}_${r.class_label}_${postLessonScopeLabel(r)}.pdf`,report:r};}finally{host.remove();}
}

function openPdfPreviewModal({title,subtitle,blob,filename,actions=[]}){
  const url=URL.createObjectURL(blob),modal=document.createElement("div");modal.className="modal-backdrop pdf-preview-backdrop";modal.innerHTML=`<div class="pdf-preview-modal"><div class="modal-head pdf-preview-head"><div><h3>${escapeHtml(title||"ตัวอย่าง PDF")}</h3><p>${escapeHtml(subtitle||"")}</p></div><button class="modal-close">×</button></div><div class="pdf-preview-document"><iframe title="PDF preview" src="${url}#toolbar=0&navpanes=0&scrollbar=1"></iframe></div><div class="pdf-preview-actions"><button class="btn btn-ghost pdf-preview-close">ปิด</button>${actions.map((a,i)=>`<button class="btn ${a.className||"btn-primary"}" data-pdf-preview-action="${i}">${escapeHtml(a.label)}</button>`).join("")}<button class="btn btn-secondary" id="pdf-preview-download">⬇ ดาวน์โหลด PDF</button></div></div>`;document.body.appendChild(modal);
  const close=()=>{URL.revokeObjectURL(url);modal.remove();};modal.querySelector(".modal-close").onclick=close;modal.querySelector(".pdf-preview-close").onclick=close;modal.querySelector("#pdf-preview-download").onclick=()=>downloadBlob(blob,filename);modal.addEventListener("click",e=>{if(e.target===modal)close();});modal.querySelectorAll("[data-pdf-preview-action]").forEach(b=>b.onclick=()=>{const action=actions[Number(b.dataset.pdfPreviewAction)];action?.onClick?.(close);});return {modal,close,url};
}

async function postLessonPreviewPdf(id){
  const r=postLessonReportById(id);if(!r)return;try{const built=await postLessonBuildPdfBlob(id),actions=[];if(academicSubmissionCanReviewUi()&&r.status==="submitted")actions.push({label:"✓ ตรวจงาน",onClick:close=>{close();postLessonReviewModal(id);}});if(postLessonCanExecutiveSignUi(r,"director"))actions.push({label:"✍ ลงนาม ผอ.",onClick:close=>{close();postLessonExecutiveSignModal(id,"director");}});openPdfPreviewModal({title:"ดูตัวอย่าง PDF — บันทึกผลหลังการจัดการเรียนรู้",subtitle:`${r.teacher_name} · ${r.subject_name} · ${r.class_label}`,blob:built.blob,filename:built.filename,actions});}catch(err){console.error(err);toast("สร้างตัวอย่าง PDF ไม่สำเร็จ",err.message||String(err),"error");}
}

async function postLessonExportPdf(id){try{const {blob,filename}=await postLessonBuildPdfBlob(id);downloadBlob(blob,filename);}catch(err){console.error(err);toast("สร้าง PDF ไม่สำเร็จ",err.message||String(err),"error");}}



// ===== Learning Sources / ระบบบันทึกแหล่งเรียนรู้ (Build 11.0.28.3) =====
const LEARNING_SOURCE_SCOPE_LABEL={internal:"ภายในโรงเรียน",external:"ภายนอกโรงเรียน"};
const LEARNING_SOURCE_STATUS_LABEL={proposed:"รอตรวจรับรอง",active:"เปิดใช้งาน",inactive:"งดใช้งาน"};
const LEARNING_SOURCE_CATEGORY_PRESETS={
  internal:["ห้องสมุด","ห้องเรียน / ห้องปฏิบัติการ","ห้องคอมพิวเตอร์","ห้องวิทยาศาสตร์","แปลงเกษตร / สวนเรียนรู้","สนามกีฬา / พื้นที่กิจกรรม","ศูนย์สื่อ / นวัตกรรม","อื่น ๆ"],
  external:["ศาสนสถาน","พิพิธภัณฑ์ / ศูนย์เรียนรู้","แหล่งธรรมชาติ","ชุมชน / ภูมิปัญญาท้องถิ่น","หน่วยงานราชการ","สถานประกอบการ / แหล่งอาชีพ","ฟาร์ม / แหล่งเกษตร","อื่น ๆ"]
};
const LEARNING_SOURCE_GRADE_PRESETS=["ปฐมวัย","ป.1-ป.3","ป.4-ป.6","ม.1-ม.3","ม.4-ม.6"];
function canManageLearningSourcesUi(){return isSuperAdminUser()||isAcademicHead();}
function learningSourceCanEditUi(s){return !!s&&(canManageLearningSourcesUi()||(s.created_by===state.user?.id&&s.status==="proposed"));}
function learningSourceCanCreateUi(){return !!state.user&&state.profile?.account_status==="active";}
function learningSourceById(id){return state.learningSources.find(x=>x.id===id)||null;}
function learningSourcePhotosFor(id){return state.learningSourcePhotos.filter(x=>x.source_id===id).sort((a,b)=>Number(b.is_cover)-Number(a.is_cover)||Number(a.sort_order||0)-Number(b.sort_order||0)||String(a.created_at).localeCompare(String(b.created_at)));}
function learningSourceCoverPhoto(id){return learningSourcePhotosFor(id)[0]||null;}
function learningSourceTypeLabel(v){return LEARNING_SOURCE_SCOPE_LABEL[v]||v||"—";}
function learningSourceStatusLabel(v){return LEARNING_SOURCE_STATUS_LABEL[v]||v||"—";}
function learningSourceArrayLabel(v){return Array.isArray(v)&&v.length?v.join(" · "):"—";}
function learningSourceSafeFilename(value){return String(value||"แหล่งเรียนรู้").replace(/[\\/:*?"<>|]+/g,"-").replace(/\s+/g,"_").slice(0,80);}
function learningSourceTextHtml(value){const t=String(value||"").trim();return t?escapeHtml(t).replaceAll("\n","<br>"):"—";}
async function loadLearningSourceWorkspace(){
  const [sourcesRes,photosRes]=await Promise.all([
    supabase.from("learning_sources").select("*").order("source_scope").order("category").order("name"),
    supabase.from("learning_source_photos").select("*").order("sort_order").order("created_at")
  ]);
  if(sourcesRes.error)throw sourcesRes.error;
  if(photosRes.error)throw photosRes.error;
  state.learningSources=sourcesRes.data||[];
  state.learningSourcePhotos=photosRes.data||[];
  const urls={};
  await Promise.all(state.learningSourcePhotos.map(async p=>{
    const {data,error}=await supabase.storage.from(p.bucket_id||"learning-sources").createSignedUrl(p.storage_path,1800);
    if(!error&&data?.signedUrl)urls[p.id]=data.signedUrl;
  }));
  state.learningSourcePhotoUrls=urls;
}
function learningSourceFiltered(){
  const q=String(state.learningSourceSearch||"").trim().toLowerCase();
  return state.learningSources.filter(s=>{
    if(state.learningSourceScopeFilter!=="all"&&s.source_scope!==state.learningSourceScopeFilter)return false;
    if(state.learningSourceCategoryFilter!=="all"&&s.category!==state.learningSourceCategoryFilter)return false;
    if(state.learningSourceStatusFilter!=="all"&&s.status!==state.learningSourceStatusFilter)return false;
    if(q){const hay=[s.name,s.category,s.location_text,s.address_text,s.organization_name,s.contact_name,s.description,s.learning_value,...(s.subject_areas||[]),...(s.grade_levels||[])].filter(Boolean).join(" ").toLowerCase();if(!hay.includes(q))return false;}
    return true;
  });
}
function learningSourceHeroHtml(){
  const all=state.learningSources,internal=all.filter(x=>x.source_scope==="internal").length,external=all.filter(x=>x.source_scope==="external").length,active=all.filter(x=>x.status==="active").length,proposed=all.filter(x=>x.status==="proposed").length;
  return `<section class="learning-source-hero"><div><span class="eyebrow dark">กลุ่มงานบริหารวิชาการ · Learning Sources</span><h2>ระบบบันทึกแหล่งเรียนรู้</h2><p>ทะเบียนกลางแหล่งเรียนรู้ภายในและภายนอกโรงเรียน พร้อมรูปภาพ ข้อมูลเชิงวิชาการ และ PDF รายแห่ง / หลายแห่ง / สรุปตาราง</p></div><div class="learning-source-hero-kpis"><span><strong>${all.length}</strong>ทั้งหมด</span><span><strong>${internal}</strong>ภายใน</span><span><strong>${external}</strong>ภายนอก</span><span><strong>${active}</strong>ใช้งาน</span>${proposed?`<span class="pending"><strong>${proposed}</strong>รอตรวจ</span>`:""}</div></section>`;
}
function learningSourceWorkspaceHtml(){
  const cats=[...new Set(state.learningSources.map(x=>x.category).filter(Boolean))].sort((a,b)=>a.localeCompare(b,"th"));
  const rows=state.learningSources;
  return `${learningSourceHeroHtml()}<section class="panel learning-source-toolbar-panel"><div class="learning-source-toolbar"><div class="field"><label>ค้นหา</label><input class="input" id="learning-source-search" value="${escapeHtml(state.learningSourceSearch||"")}" placeholder="ชื่อแหล่งเรียนรู้ / ที่ตั้ง / องค์ความรู้"></div><div class="field"><label>ประเภท</label><select class="select" id="learning-source-scope"><option value="all">ทุกประเภท</option><option value="internal" ${state.learningSourceScopeFilter==="internal"?"selected":""}>ภายในโรงเรียน</option><option value="external" ${state.learningSourceScopeFilter==="external"?"selected":""}>ภายนอกโรงเรียน</option></select></div><div class="field"><label>หมวดหมู่</label><select class="select" id="learning-source-category"><option value="all">ทุกหมวดหมู่</option>${cats.map(x=>`<option value="${escapeHtml(x)}" ${state.learningSourceCategoryFilter===x?"selected":""}>${escapeHtml(x)}</option>`).join("")}</select></div><div class="field"><label>สถานะ</label><select class="select" id="learning-source-status"><option value="all">ทุกสถานะ</option>${Object.entries(LEARNING_SOURCE_STATUS_LABEL).map(([k,v])=>`<option value="${k}" ${state.learningSourceStatusFilter===k?"selected":""}>${v}</option>`).join("")}</select></div></div><div class="learning-source-toolbar-actions">${learningSourceCanCreateUi()?`<button class="btn btn-primary" id="learning-source-create">＋ ${canManageLearningSourcesUi()?"เพิ่มแหล่งเรียนรู้":"เสนอแหล่งเรียนรู้"}</button>`:""}<button class="btn btn-secondary" id="learning-source-export-book">PDF เล่มตามตัวกรอง</button><button class="btn btn-secondary" id="learning-source-export-summary">PDF สรุปตาราง</button><button class="btn btn-ghost" id="learning-source-export-selected">PDF รายการที่เลือก</button></div></section><section class="panel"><div class="panel-head"><div class="panel-title-wrap"><h3>ทะเบียนแหล่งเรียนรู้</h3><p>ติ๊กรายการเพื่อรวมหลายแห่งเป็น PDF เดียว หรือเลือกตัวกรองประเภท/หมวดหมู่แล้ว Export ได้ทันที</p></div><span class="learning-source-filter-count" id="learning-source-filter-count">${rows.length} รายการ</span></div>${rows.length?`<div class="table-wrap"><table class="table learning-source-table"><thead><tr><th style="width:38px"><input type="checkbox" id="learning-source-check-all"></th><th style="width:86px">ภาพ</th><th>แหล่งเรียนรู้</th><th>ประเภท</th><th>หมวดหมู่</th><th>ที่ตั้ง</th><th>สถานะ</th><th style="width:150px"></th></tr></thead><tbody>${rows.map(s=>{const cover=learningSourceCoverPhoto(s.id),url=cover?state.learningSourcePhotoUrls[cover.id]:null;return `<tr data-learning-source-row="${s.id}"><td><input type="checkbox" class="learning-source-select" value="${s.id}"></td><td>${url?`<img class="learning-source-thumb" src="${escapeHtml(url)}" alt="">`:`<div class="learning-source-thumb empty">ภาพ</div>`}</td><td><strong>${escapeHtml(s.name)}</strong><br><span class="table-muted">${escapeHtml((s.subject_areas||[]).slice(0,3).join(" · ")||"ยังไม่ระบุกลุ่มสาระ")}</span></td><td><span class="learning-source-scope ${s.source_scope}">${learningSourceTypeLabel(s.source_scope)}</span></td><td>${escapeHtml(s.category)}</td><td>${escapeHtml(s.location_text||s.address_text||"—")}</td><td><span class="learning-source-status ${s.status}">${learningSourceStatusLabel(s.status)}</span></td><td><div class="admin-actions"><button class="btn btn-ghost" data-learning-source-detail="${s.id}">รายละเอียด</button>${learningSourceCanEditUi(s)?`<button class="btn btn-secondary" data-learning-source-edit="${s.id}">แก้ไข</button>`:""}</div></td></tr>`;}).join("")}</tbody></table><div class="empty learning-source-filter-empty" id="learning-source-filter-empty" hidden><strong>ไม่พบรายการตามตัวกรอง</strong><span>ลองเปลี่ยนประเภท หมวดหมู่ สถานะ หรือคำค้น</span></div></div>`:`<div class="empty"><strong>ยังไม่มีแหล่งเรียนรู้</strong><span>เริ่มเพิ่มแหล่งเรียนรู้ภายในโรงเรียน หรือเสนอแหล่งเรียนรู้ภายนอกได้เลย</span></div>`}</section>`;
}
function learningSourceApplyClientFilter(){
  const ids=new Set(learningSourceFiltered().map(x=>x.id));let shown=0;
  document.querySelectorAll("[data-learning-source-row]").forEach(tr=>{const show=ids.has(tr.dataset.learningSourceRow);tr.hidden=!show;if(show)shown++;});
  const count=document.querySelector("#learning-source-filter-count");if(count)count.textContent=`${shown} รายการ`;
  const empty=document.querySelector("#learning-source-filter-empty");if(empty)empty.hidden=shown!==0;
  const all=document.querySelector("#learning-source-check-all");if(all)all.checked=false;
}
