function officialAttendanceDateObj(value){if(!value)return null;if(value instanceof Date)return new Date(value.getFullYear(),value.getMonth(),value.getDate());const m=String(value).match(/^(\d{4})-(\d{2})-(\d{2})/);return m?new Date(Number(m[1]),Number(m[2])-1,Number(m[3])):new Date(value);}
