function officialAttendanceRosterPosition(userId){return state.officialAttendancePersonnel.find(x=>x.user_id===userId)?.position_title||ROLE_LABEL[state.officialAttendanceRoster.find(x=>x.id===userId)?.role]||"บุคลากร";}
