  const dayPolicy=officialAttendanceEffectiveDay(date),today=officialAttendanceDateValue(),future=String(date)>today;const now=new Date(),nowHm=`${String(now.getHours()).padStart(2,"0")}:${String(now.getMinutes()).padStart(2,"0")}:${String(now.getSeconds()).padStart(2,"0")}`,closeHm=officialAttendanceClockKey(dayPolicy.closeTime||"23:59:59");const pendingToday=String(date)===today&&dayPolicy.isOpen&&nowHm<=closeHm;
