function officialAttendanceKpis(date){const s=officialAttendanceSummaryForDate(date);return `<div class="attendance-kpis"><article><span>บุคลากรทั้งหมด</span><strong>${s.total}</strong></article><article><span>ลงเวลาแล้ว</span><strong>${s.checked}</strong></article><article><span>มาสาย</span><strong>${s.late}</strong></article><article><span>ลา</span><strong>${s.leave}</strong></article><article><span>ไปราชการ</span><strong>${s.duty}</strong></article><article class="${s.missing?"warning":""}"><span>${s.pending&&!s.missing?"ยังไม่ได้เช็กชื่อ":"ไม่ได้เช็กชื่อ"}</span><strong>${s.notChecked}</strong></article></div>`;}
