function officialAttendanceDescriptorDistance(a,b){if(!Array.isArray(a)||!Array.isArray(b)||a.length!==b.length)return Infinity;let sum=0;for(let i=0;i<a.length;i++){const d=Number(a[i]||0)-Number(b[i]||0);sum+=d*d;}return Math.sqrt(sum);}
