function officialAttendanceFaceManagerModal(){if(!officialAttendanceCanManageUi())return;const statuses=new Map((state.officialAttendanceFaceStatuses||[]).map(x=>[x.user_id,x])),m=document.createElement("div");m.className="modal-backdrop";m.innerHTML=`<div class="modal modal-wide"><div class="modal-head"><div><h3>จัดการการลงทะเบียนใบหน้า</h3><p>ผู้ดูแลเห็นเฉพาะสถานะการลงทะเบียน ไม่สามารถดู Face Template ของบุคลากร</p></div><button class="modal-close">×</button></div><div class="table-wrap"><table class="table"><thead><tr><th>ชื่อ–นามสกุล</th><th>ตำแหน่ง</th><th>สถานะ</th><th>ลงทะเบียนเมื่อ</th><th></th></tr></thead><tbody>${(state.officialAttendanceRoster||[]).filter(p=>p.role!=="super_admin").map(p=>{const st=statuses.get(p.id);return `<tr><td><strong>${escapeHtml(p.full_name||p.email||"-")}</strong></td><td>${escapeHtml(officialAttendanceRosterPosition(p.id))}</td><td><span class="attendance-status ${st?.registered?"on_time":"pending_checkin"}">${st?.registered?"ลงทะเบียนแล้ว":"ยังไม่ลงทะเบียน"}</span></td><td>${st?.registered_at?escapeHtml(new Intl.DateTimeFormat("th-TH",{dateStyle:"medium",timeStyle:"short",timeZone:"Asia/Bangkok"}).format(new Date(st.registered_at))):"—"}</td><td>${st?.registered?`<button class="btn btn-danger btn-sm" data-attendance-face-reset="${p.id}">รีเซ็ตใบหน้า</button>`:""}</td></tr>`;}).join("")}</tbody></table></div><div class="modal-actions"><button class="btn btn-ghost modal-cancel">ปิด</button></div></div>`;document.body.appendChild(m);const close=()=>m.remove();m.querySelector(".modal-close").onclick=close;m.querySelector(".modal-cancel").onclick=close;m.querySelectorAll("[data-attendance-face-reset]").forEach(b=>b.onclick=async()=>{const p=(state.officialAttendanceRoster||[]).find(x=>x.id===b.dataset.attendanceFaceReset);if(!window.confirm(`รีเซ็ตข้อมูลใบหน้าของ ${p?.full_name||"บุคลากรรายนี้"} หรือไม่?`))return;buttonLoading(b,true,"กำลังรีเซ็ต...");const {error}=await supabase.rpc("admin_reset_official_attendance_face",{p_user_id:b.dataset.attendanceFaceReset});if(error){buttonLoading(b,false);return toast("รีเซ็ตไม่สำเร็จ",error.message,"error");}toast("รีเซ็ตข้อมูลใบหน้าแล้ว","บุคลากรต้องลงทะเบียนใบหน้าใหม่ก่อนใช้งาน","success");close();await loadOfficialAttendanceWorkspace();await renderDashboard();});}
async function officialAttendanceDeleteFaceRegistration(button){if(!state.officialAttendanceFaceStatus?.registered)return;if(!window.confirm("ลบข้อมูลใบหน้าที่ลงทะเบียนไว้หรือไม่? หลังลบจะใช้โหมด Face Verification ไม่ได้จนกว่าจะลงทะเบียนใหม่"))return;buttonLoading(button,true,"กำลังลบ...");try{const {error}=await supabase.rpc("delete_my_official_attendance_face");if(error)throw error;toast("ลบข้อมูลใบหน้าแล้ว","สามารถลงทะเบียนใหม่ได้ทุกเมื่อ","success");await loadOfficialAttendanceWorkspace();await renderDashboard();}catch(err){toast("ลบข้อมูลไม่สำเร็จ",err.message||String(err),"error");}finally{buttonLoading(button,false);}}
function officialAttendanceSettingsModal(){
  if(!officialAttendanceCanManageUi())return;const s=state.officialAttendanceSettings||{},mode=s.attendance_mode||"gps",rootAdmin=isSuperAdminUser(),m=document.createElement("div");m.className="modal-backdrop";m.innerHTML=`<div class="modal modal-wide"><div class="modal-head"><div><h3>ตั้งค่าระบบลงเวลาปฏิบัติราชการ</h3><p>กำหนดรูปแบบการลงเวลา พิกัดโรงเรียน รัศมี และช่วงเวลา</p></div><button class="modal-close">×</button></div><form id="attendance-settings-form" class="form-grid"><label class="attendance-setting-switch"><input type="checkbox" name="enabled" ${s.enabled?"checked":""}><span><strong>เปิดระบบลงเวลา</strong><small>ปิดได้ในช่วงปิดเทอม</small></span></label>${rootAdmin?`<label class="attendance-setting-switch attendance-test-toggle"><input type="checkbox" name="test_center_enabled" ${s.test_center_enabled?"checked":""}><span><strong>🧪 เปิดศูนย์ทดสอบการลงเวลา</strong><small>เฉพาะ Super Admin เท่านั้นที่เปิด/ปิดได้ · ไม่กระทบข้อมูลลงเวลาจริง</small></span></label>`:""}<div class="personnel-form-section"><strong>รูปแบบการลงเวลา</strong></div><div class="attendance-mode-options form-span-2">${[["gps","📍","GPS ปกติ","กดลงเวลาและตรวจ GPS ทันที"],["qr","▦","QR Code + GPS","ต้องสแกน QR ประจำวันก่อนตรวจ GPS"],["face","🙂","Face Verification + GPS","ต้องยืนยันใบหน้าที่ลงทะเบียนก่อนตรวจ GPS"]].map(([v,i,t,d])=>`<label class="attendance-mode-option"><input type="radio" name="attendance_mode" value="${v}" ${mode===v?"checked":""}><span class="attendance-mode-icon">${i}</span><span><strong>${t}</strong><small>${d}</small></span></label>`).join("")}</div><div class="attendance-mode-note form-span-2">เลือกใช้ได้ทีละโหมดเดียว และเมื่อมีคนลงเวลาในวันนั้นแล้ว ระบบจะล็อกโหมดจนจบวัน · GPS เป็นเงื่อนไขบังคับทุกโหมด</div><div class="personnel-form-section"><strong>พิกัดโรงเรียน</strong></div><div class="field"><label>Latitude</label><input class="input" name="school_latitude" type="number" step="0.0000001" value="${s.school_latitude??""}" required></div><div class="field"><label>Longitude</label><input class="input" name="school_longitude" type="number" step="0.0000001" value="${s.school_longitude??""}" required></div><div class="field"><label>รัศมีที่อนุญาต (เมตร)</label><input class="input" name="allowed_radius_m" type="number" min="20" max="5000" value="${s.allowed_radius_m||250}" required></div><div class="field"><label>GPS คลาดเคลื่อนได้ไม่เกิน (เมตร)</label><input class="input" name="max_accuracy_m" type="number" min="10" max="2000" value="${s.max_accuracy_m||150}" required></div><div class="field form-span-2"><button type="button" class="btn btn-secondary" id="attendance-use-current-location">📍 ใช้ตำแหน่งปัจจุบันเป็นพิกัดโรงเรียน</button><span class="helper" id="attendance-location-helper">ควรตั้งค่าขณะอยู่บริเวณโรงเรียนและเปิด GPS แบบแม่นยำ</span></div><div class="personnel-form-section"><strong>ช่วงเวลา</strong></div><div class="field"><label>เปิดเช็กชื่อ</label><input class="input" name="checkin_open_time" type="time" value="${officialAttendanceTime(s.checkin_open_time||"06:00")}" required></div><div class="field"><label>ตรงเวลาถึง</label><input class="input" name="ontime_until" type="time" value="${officialAttendanceTime(s.ontime_until||"08:30")}" required></div><div class="field"><label>ปิดรับเช็กชื่อ</label><input class="input" name="checkin_close_time" type="time" value="${officialAttendanceTime(s.checkin_close_time||"23:59")}" required></div><div class="field"><label>เวลาสิ้นสุดราชการ</label><input class="input" name="work_end_time" type="time" value="${officialAttendanceTime(s.work_end_time||"16:30")}" required></div><div class="field"><label>เปิดใช้ตั้งแต่วันที่</label><input class="input" name="active_from" type="date" value="${s.active_from||""}"></div><div class="field"><label>ถึงวันที่</label><input class="input" name="active_to" type="date" value="${s.active_to||""}"></div><div class="personnel-form-section"><strong>วันปฏิบัติราชการประจำสัปดาห์</strong></div><div class="attendance-weekdays form-span-2">${[["monday","จันทร์"],["tuesday","อังคาร"],["wednesday","พุธ"],["thursday","พฤหัสบดี"],["friday","ศุกร์"],["saturday","เสาร์"],["sunday","อาทิตย์"]].map(([k,l])=>`<label><input type="checkbox" name="${k}" ${s[k]?"checked":""}><span>${l}</span></label>`).join("")}</div></form><div class="modal-actions"><button class="btn btn-ghost modal-cancel">ยกเลิก</button><button class="btn btn-primary" id="attendance-settings-save">บันทึกการตั้งค่า</button></div></div>`;document.body.appendChild(m);const close=()=>m.remove();m.querySelector(".modal-close").onclick=close;m.querySelector(".modal-cancel").onclick=close;
  m.querySelector("#attendance-use-current-location").onclick=e=>{if(!navigator.geolocation)return toast("อุปกรณ์ไม่รองรับ GPS","","error");buttonLoading(e.currentTarget,true,"กำลังหาพิกัด...");navigator.geolocation.getCurrentPosition(pos=>{m.querySelector('[name="school_latitude"]').value=pos.coords.latitude.toFixed(7);m.querySelector('[name="school_longitude"]').value=pos.coords.longitude.toFixed(7);m.querySelector("#attendance-location-helper").textContent=`พิกัดจากเครื่อง · ความแม่นยำประมาณ ±${Math.round(pos.coords.accuracy)} เมตร`;buttonLoading(e.currentTarget,false);},err=>{buttonLoading(e.currentTarget,false);toast("หาพิกัดไม่สำเร็จ",err.code===1?"กรุณาอนุญาตตำแหน่ง":"กรุณาลองใหม่","error");},{enableHighAccuracy:true,timeout:20000,maximumAge:0});};
  m.querySelector("#attendance-settings-save").onclick=async e=>{const form=m.querySelector("#attendance-settings-form");if(!form.reportValidity())return;const f=new FormData(form),latRaw=String(f.get("school_latitude")||"").trim(),lngRaw=String(f.get("school_longitude")||"").trim(),payload={enabled:f.get("enabled")==="on",...(rootAdmin?{test_center_enabled:f.get("test_center_enabled")==="on"}:{}),attendance_mode:String(f.get("attendance_mode")||"gps"),school_latitude:latRaw?Number(latRaw):null,school_longitude:lngRaw?Number(lngRaw):null,allowed_radius_m:Number(f.get("allowed_radius_m")),max_accuracy_m:Number(f.get("max_accuracy_m")),checkin_open_time:f.get("checkin_open_time"),ontime_until:f.get("ontime_until"),checkin_close_time:f.get("checkin_close_time"),work_end_time:f.get("work_end_time"),active_from:f.get("active_from")||null,active_to:f.get("active_to")||null,monday:f.get("monday")==="on",tuesday:f.get("tuesday")==="on",wednesday:f.get("wednesday")==="on",thursday:f.get("thursday")==="on",friday:f.get("friday")==="on",saturday:f.get("saturday")==="on",sunday:f.get("sunday")==="on",updated_by:state.user.id,updated_at:new Date().toISOString()};if(payload.enabled&&(!Number.isFinite(payload.school_latitude)||!Number.isFinite(payload.school_longitude)))return toast("กรุณากำหนดพิกัดโรงเรียน","","error");buttonLoading(e.currentTarget,true,"กำลังบันทึก...");const {error}=await supabase.from("official_attendance_settings").update(payload).eq("id",1);buttonLoading(e.currentTarget,false);if(error)return toast("บันทึกไม่สำเร็จ",error.message,"error");close();toast("บันทึกการตั้งค่าแล้ว",`โหมดหลัก: ${ATTENDANCE_MODE_LABEL[payload.attendance_mode]}`,"success");await loadOfficialAttendanceWorkspace();await renderDashboard();};
}
function officialAttendanceDaySettingModal(){
  if(!officialAttendanceCanManageUi())return;const selected=state.officialAttendanceReportDate||officialAttendanceDateValue(),existing=(state.officialAttendanceDaySettings||[]).find(x=>String(x.attendance_date)===selected),m=document.createElement("div");m.className="modal-backdrop";m.innerHTML=`<div class="modal"><div class="modal-head"><div><h3>กำหนดวันเปิด/ปิดพิเศษ</h3><p>ใช้สำหรับวันหยุด ปิดเทอม เปลี่ยนเวลา หรือเปลี่ยนโหมดเฉพาะวัน</p></div><button class="modal-close">×</button></div><form id="attendance-day-form" class="form-grid"><div class="field"><label>วันที่</label><input class="input" name="attendance_date" type="date" value="${existing?.attendance_date||selected}" required></div><div class="field"><label>สถานะ</label><select class="select" name="is_open"><option value="true" ${existing?.is_open!==false?"selected":""}>เปิดลงเวลา</option><option value="false" ${existing?.is_open===false?"selected":""}>ปิดลงเวลา</option></select></div><div class="field form-span-2"><label>รูปแบบการลงเวลาของวันนี้</label><select class="select" name="attendance_mode"><option value="" ${!existing?.attendance_mode?"selected":""}>ใช้ค่ากลางของระบบ (${escapeHtml(ATTENDANCE_MODE_LABEL[state.officialAttendanceSettings?.attendance_mode||"gps"])})</option><option value="gps" ${existing?.attendance_mode==="gps"?"selected":""}>GPS ปกติ</option><option value="qr" ${existing?.attendance_mode==="qr"?"selected":""}>QR Code + GPS</option><option value="face" ${existing?.attendance_mode==="face"?"selected":""}>Face Verification + GPS</option></select><span class="helper">หากมีผู้ลงเวลาแล้ว ระบบจะไม่อนุญาตให้เปลี่ยนโหมดของวันนั้น</span></div><div class="field"><label>เปิดเช็กชื่อ (เว้นว่าง=ค่ากลาง)</label><input class="input" name="checkin_open_time" type="time" value="${existing?.checkin_open_time?officialAttendanceTime(existing.checkin_open_time):""}"></div><div class="field"><label>ตรงเวลาถึง</label><input class="input" name="ontime_until" type="time" value="${existing?.ontime_until?officialAttendanceTime(existing.ontime_until):""}"></div><div class="field"><label>ปิดรับเช็กชื่อ</label><input class="input" name="checkin_close_time" type="time" value="${existing?.checkin_close_time?officialAttendanceTime(existing.checkin_close_time):""}"></div><div class="field"><label>เวลาสิ้นสุดราชการ</label><input class="input" name="work_end_time" type="time" value="${existing?.work_end_time?officialAttendanceTime(existing.work_end_time):""}"></div><div class="field form-span-2"><label>หมายเหตุ</label><input class="input" name="note" value="${escapeHtml(existing?.note||"")}" placeholder="เช่น ปิดภาคเรียน / วันหยุดพิเศษ"></div></form><div class="modal-actions">${existing?`<button class="btn btn-danger" id="attendance-day-delete">ลบค่าพิเศษ</button>`:""}<button class="btn btn-ghost modal-cancel">ยกเลิก</button><button class="btn btn-primary" id="attendance-day-save">บันทึก</button></div></div>`;document.body.appendChild(m);const close=()=>m.remove();m.querySelector(".modal-close").onclick=close;m.querySelector(".modal-cancel").onclick=close;m.querySelector("#attendance-day-delete")?.addEventListener("click",async e=>{if(!window.confirm("ลบค่าพิเศษของวันนี้ และกลับไปใช้ค่ากลาง?"))return;buttonLoading(e.currentTarget,true,"กำลังลบ...");const {error}=await supabase.from("official_attendance_day_settings").delete().eq("attendance_date",existing.attendance_date);if(error){buttonLoading(e.currentTarget,false);return toast("ลบไม่สำเร็จ",error.message,"error");}close();await loadOfficialAttendanceWorkspace();await renderDashboard();});m.querySelector("#attendance-day-save").onclick=async e=>{const f=new FormData(m.querySelector("#attendance-day-form")),payload={attendance_date:f.get("attendance_date"),is_open:f.get("is_open")==="true",attendance_mode:f.get("attendance_mode")||null,checkin_open_time:f.get("checkin_open_time")||null,ontime_until:f.get("ontime_until")||null,checkin_close_time:f.get("checkin_close_time")||null,work_end_time:f.get("work_end_time")||null,note:String(f.get("note")||"").trim()||null,updated_by:state.user.id,updated_at:new Date().toISOString()};buttonLoading(e.currentTarget,true,"กำลังบันทึก...");const {error}=await supabase.from("official_attendance_day_settings").upsert(payload,{onConflict:"attendance_date"});buttonLoading(e.currentTarget,false);if(error)return toast("บันทึกไม่สำเร็จ",error.message,"error");close();toast("บันทึกวันพิเศษแล้ว",payload.is_open?`เปิดลงเวลา · ${ATTENDANCE_MODE_LABEL[payload.attendance_mode||state.officialAttendanceSettings?.attendance_mode||"gps"]}`:"วันนี้ปิดลงเวลา","success");await loadOfficialAttendanceWorkspace();await renderDashboard();};
}
function officialAttendanceDutyModal(){if(!officialAttendanceCanManageUi())return;const date=state.officialAttendanceReportDate||officialAttendanceDateValue(),m=document.createElement("div");m.className="modal-backdrop";m.innerHTML=`<div class="modal"><div class="modal-head"><div><h3>บันทึกไปราชการ / ปฏิบัติงานนอกสถานที่</h3><p>รายการนี้จะไม่นับบุคลากรเป็นผู้ขาดเช็กชื่อในวันดังกล่าว</p></div><button class="modal-close">×</button></div><form id="attendance-duty-form" class="form-grid"><div class="field"><label>วันที่</label><input class="input" name="duty_date" type="date" value="${date}" required></div><div class="field"><label>บุคลากร</label><select class="select" name="user_id" required><option value="">— เลือกบุคลากร —</option>${(state.officialAttendanceRoster||[]).filter(p=>p.role!=="super_admin").map(p=>`<option value="${p.id}">${escapeHtml(p.full_name||p.email||"-")} · ${escapeHtml(officialAttendanceRosterPosition(p.id))}</option>`).join("")}</select></div><div class="field"><label>ประเภท</label><select class="select" name="duty_type"><option value="official_duty">ไปราชการ</option><option value="training">อบรม / สัมมนา</option><option value="other">ปฏิบัติหน้าที่อื่น</option></select></div><div class="field"><label>สถานที่</label><input class="input" name="duty_location" placeholder="เช่น สพป.เชียงใหม่ เขต 3"></div><div class="field form-span-2"><label>หมายเหตุ</label><textarea class="input textarea" name="note" placeholder="เลขคำสั่ง / รายละเอียดเพิ่มเติม"></textarea></div></form><div class="modal-actions"><button class="btn btn-ghost modal-cancel">ยกเลิก</button><button class="btn btn-primary" id="attendance-duty-save">บันทึก</button></div></div>`;document.body.appendChild(m);const close=()=>m.remove();m.querySelector(".modal-close").onclick=close;m.querySelector(".modal-cancel").onclick=close;m.querySelector("#attendance-duty-save").onclick=async e=>{const f=new FormData(m.querySelector("#attendance-duty-form")),uid=f.get("user_id");if(!uid)return toast("กรุณาเลือกบุคลากร","","error");const payload={user_id:uid,duty_date:f.get("duty_date"),duty_type:f.get("duty_type"),duty_location:String(f.get("duty_location")||"").trim()||null,note:String(f.get("note")||"").trim()||null,created_by:state.user.id,updated_by:state.user.id,updated_at:new Date().toISOString()};buttonLoading(e.currentTarget,true,"กำลังบันทึก...");const {error}=await supabase.from("official_attendance_duty_records").upsert(payload,{onConflict:"user_id,duty_date"});buttonLoading(e.currentTarget,false);if(error)return toast("บันทึกไม่สำเร็จ",error.message,"error");close();toast("บันทึกสถานะไปราชการแล้ว","รายการจะถูกนำไปสรุปในรายงานอัตโนมัติ","success");await loadOfficialAttendanceWorkspace();await renderDashboard();};}
async function officialAttendanceSignatureDataUrl(record){if(!record?.signature_path)return null;const key=`${record.signature_bucket||"signatures"}:${record.signature_path}`;if(officialAttendanceSignatureCache.has(key))return officialAttendanceSignatureCache.get(key);const {data,error}=await supabase.storage.from(record.signature_bucket||"signatures").download(record.signature_path);if(error){console.warn("attendance signature download",error);return null;}const url=await blobToDataUrl(data);officialAttendanceSignatureCache.set(key,url);return url;}
function officialAttendancePdfStyles(){return `${officialPdfFontFaceCss()}*{box-sizing:border-box}html,body{width:100%;margin:0;padding:0}body{font-family:"TH SarabunIT๙","THSarabunIT๙",serif;color:#111;background:#fff}@page{size:A4 portrait;margin:12mm}.attendance-pdf{width:100%;max-width:100%;margin:0 auto;font-size:14pt;line-height:1.22;overflow:visible}.attendance-pdf-head{text-align:center;margin-bottom:3mm}.attendance-pdf-logo{width:21mm;height:21mm;object-fit:contain}.attendance-pdf-head h1{font-size:19pt;margin:.8mm 0 0}.attendance-pdf-head h2{font-size:17pt;margin:.7mm 0}.attendance-pdf-head p{font-size:13.5pt;margin:0}.attendance-pdf-meta{display:flex;justify-content:center;flex-wrap:wrap;gap:3mm 8mm;margin:2mm 0 3mm;font-size:14pt}.attendance-pdf-table{width:100%;max-width:100%;border-collapse:collapse;table-layout:fixed;border:1px solid #222}.attendance-pdf-table thead{display:table-header-group}.attendance-pdf-table tr{break-inside:avoid;page-break-inside:avoid}.attendance-pdf-table tbody tr{height:12mm}.attendance-pdf-table th,.attendance-pdf-table td{border:1px solid #222;padding:1.05mm .65mm;vertical-align:middle;overflow-wrap:anywhere;word-break:normal}.attendance-pdf-table th{text-align:center;font-size:14pt;line-height:1.12;background:#f4f4f4}.attendance-pdf-table td{font-size:14pt;line-height:1.14}.attendance-pdf-center{text-align:center}.attendance-pdf-person-cell{height:12mm;vertical-align:middle!important;text-align:left}.attendance-pdf-name{font-size:14.25pt;font-weight:700;line-height:1.1;margin:0}.attendance-pdf-table small{font-size:11.5pt;line-height:1.05}.attendance-pdf-sign{height:10mm;text-align:center;padding-left:.35mm!important;padding-right:.35mm!important}.attendance-pdf-sign img{max-height:8.8mm;max-width:22mm;object-fit:contain}.attendance-pdf-note-cell{font-size:13.5pt!important;line-height:1.12!important}.attendance-pdf-summary{margin-top:4mm;border:1px solid #333;padding:2.5mm;break-inside:avoid}.attendance-pdf-summary-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1.5mm 3mm;font-size:14pt}.attendance-pdf-note{margin-top:4mm;break-inside:avoid}.attendance-pdf-note h3{font-size:15.5pt;margin:0 0 1.5mm}.attendance-pdf-note ol{margin:0;padding-left:8mm;font-size:14pt}.attendance-pdf-footer{margin-top:4mm;text-align:right;font-size:11.5pt;color:#444}.attendance-summary-pdf-table th,.attendance-summary-pdf-table td{font-size:13.5pt;padding:1.35mm .7mm}.attendance-summary-pdf-table td:not(:first-child){text-align:center}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}.attendance-pdf{width:100%}}`;}
async function officialAttendanceDailyPdf(date){const summary=officialAttendanceSummaryForDate(date),rows=summary.rows,logo=await schoolLogoDataUrl(),sigMap=new Map();for(const x of rows){if(x.record){const url=await officialAttendanceSignatureDataUrl(x.record);if(url)sigMap.set(x.record.id,url);}}const dutyRows=rows.filter(x=>x.code==="duty"),dutySection=dutyRows.length?`<section class="attendance-pdf-note"><h3>ผู้ไปราชการ / อบรม / ปฏิบัติหน้าที่นอกสถานที่ (${dutyRows.length} คน)</h3><ol>${dutyRows.map(x=>`<li><strong>${escapeHtml(x.user.full_name||x.user.email||"-")}</strong> — ${escapeHtml(ATTENDANCE_DUTY_LABEL[x.duty?.duty_type]||"ไปราชการ")}${x.duty?.duty_location?` — ${escapeHtml(x.duty.duty_location)}`:""}${x.duty?.note?` — ${escapeHtml(x.duty.note)}`:""}</li>`).join("")}</ol></section>`:"";const body=`<article class="attendance-pdf"><header class="attendance-pdf-head">${logo?`<img class="attendance-pdf-logo" src="${logo}" alt="ตราโรงเรียน">`:""}<h1>${escapeHtml(schoolName())}</h1><h2>บัญชีลงเวลาปฏิบัติราชการ</h2><p>${escapeHtml(schoolAddress())} · ${escapeHtml(educationOffice())}</p></header><div class="attendance-pdf-meta"><span><strong>วันที่</strong> ${officialAttendanceThaiDate(date)}</span><span><strong>บุคลากรที่ต้องลงเวลา</strong> ${summary.total} คน</span></div><table class="attendance-pdf-table"><colgroup><col style="width:5%"><col style="width:25%"><col style="width:12%"><col style="width:15%"><col style="width:12%"><col style="width:15%"><col style="width:16%"></colgroup><thead><tr><th>ที่</th><th>ชื่อ–นามสกุล</th><th>เวลาเข้า</th><th>ลายเซ็น</th><th>เวลากลับ</th><th>ลายเซ็น</th><th>หมายเหตุ</th></tr></thead><tbody>${rows.map(x=>{const img=x.record?sigMap.get(x.record.id):null;return `<tr><td class="attendance-pdf-center">${x.arrivalOrder||"—"}</td><td class="attendance-pdf-person-cell"><div class="attendance-pdf-name">${escapeHtml(x.user.full_name||x.user.email||"-")}</div></td><td class="attendance-pdf-center">${x.record?`${officialAttendanceTime(x.record.checkin_at,true)} น.`:"—"}</td><td class="attendance-pdf-sign">${img?`<img src="${img}" alt="ลายเซ็น">`:"—"}</td><td class="attendance-pdf-center">${x.record?`${officialAttendanceTime(x.record.work_end_time_snapshot)} น.`:"—"}</td><td class="attendance-pdf-sign">${img?`<img src="${img}" alt="ลายเซ็น">`:"—"}</td><td class="attendance-pdf-note-cell">${escapeHtml(x.note||"—")}</td></tr>`;}).join("")}</tbody></table><section class="attendance-pdf-summary"><div class="attendance-pdf-summary-grid"><span>บุคลากรทั้งหมด <strong>${summary.total}</strong> คน</span><span>ลงเวลา <strong>${summary.checked}</strong> คน</span><span>ตรงเวลา <strong>${summary.onTime}</strong> คน</span><span>สาย <strong>${summary.late}</strong> คน</span><span>ลา <strong>${summary.leave}</strong> คน</span><span>ไปราชการ <strong>${summary.duty}</strong> คน</span></div></section>${dutySection}<div class="attendance-pdf-footer">สร้างจาก BNK School OS · ระบบลงเวลาปฏิบัติราชการ</div></article>`;openPrintPreview(body,officialAttendancePdfStyles(),`บัญชีลงเวลาปฏิบัติราชการ ${officialAttendanceThaiDate(date)}`);}
async function officialAttendanceSummaryPdf(start,end,title){const data=officialAttendanceMonthlySummary(start,end),logo=await schoolLogoDataUrl(),body=`<article class="attendance-pdf"><header class="attendance-pdf-head">${logo?`<img class="attendance-pdf-logo" src="${logo}" alt="ตราโรงเรียน">`:""}<h1>${escapeHtml(schoolName())}</h1><h2>${escapeHtml(title)}</h2><p>${escapeHtml(schoolAddress())} · ${escapeHtml(educationOffice())}</p></header><div class="attendance-pdf-meta"><span>${officialAttendanceThaiDate(start)} – ${officialAttendanceThaiDate(end)}</span><span>วันปฏิบัติราชการ <strong>${data.workdays.length}</strong> วัน · ผ่านแล้ว ${data.elapsedWorkdays.length} วัน</span></div><table class="attendance-pdf-table attendance-summary-pdf-table"><thead><tr><th style="width:9mm">ที่</th><th>ชื่อ–นามสกุล / ตำแหน่ง</th><th style="width:18mm">วันเต็ม</th><th style="width:18mm">ลงเวลา</th><th style="width:15mm">สาย</th><th style="width:15mm">ลา</th><th style="width:21mm">ไปราชการ</th><th style="width:21mm">ขาดเช็กชื่อ</th></tr></thead><tbody>${data.rows.map((x,i)=>`<tr><td class="attendance-pdf-center">${i+1}</td><td><strong>${escapeHtml(x.user.full_name||x.user.email||"-")}</strong><br><small>${escapeHtml(x.position||"")}</small></td><td>${x.expected}</td><td>${x.checked}</td><td>${x.late}</td><td>${x.leave}</td><td>${x.duty}</td><td>${x.missing}</td></tr>`).join("")}</tbody></table><div class="attendance-pdf-footer">หมายเหตุ: วันลาอ้างอิงจากคำขอลาที่อนุมัติแล้ว · ไปราชการอ้างอิงจากรายการที่ฝ่ายบุคคลบันทึก</div></article>`;openPrintPreview(body,officialAttendancePdfStyles(),title);}
async function officialAttendanceExportCurrent(){const view=state.officialAttendanceView||"daily";if(view==="daily")return officialAttendanceDailyPdf(state.officialAttendanceReportDate);if(view==="monthly"){const r=officialAttendanceRangeForMonth();return officialAttendanceSummaryPdf(r.start,r.end,`สรุปการลงเวลาประจำเดือน ${state.officialAttendanceReportMonth}`);}if(view==="term"){const r=officialAttendanceRangeForTerm(state.officialAttendanceReportAcademicYear,state.officialAttendanceReportSemester);return officialAttendanceSummaryPdf(r.start,r.end,`สรุปการลงเวลาภาคเรียนที่ ${state.officialAttendanceReportSemester} ปีการศึกษา ${state.officialAttendanceReportAcademicYear}`);}const r=officialAttendanceRangeForYear();return officialAttendanceSummaryPdf(r.start,r.end,`สรุปการลงเวลาปีการศึกษา ${state.officialAttendanceReportAcademicYear}`);}

async function officialAttendanceCancelRecordModal(recordId){
  if(!officialAttendanceCanCancelUi())return toast("ไม่มีสิทธิ์ยกเลิกการลงเวลา","สิทธิ์นี้สำหรับฝ่ายบุคคล/เจ้าหน้าที่บุคคล และ Super Admin","error");
  const record=(state.officialAttendanceRecords||[]).find(r=>r.id===recordId);
  if(!record)return toast("ไม่พบรายการลงเวลา","รายการอาจถูกยกเลิกไปแล้ว กรุณารีเฟรชข้อมูล","error");
  const person=(state.officialAttendanceRoster||[]).find(p=>p.id===record.user_id),name=record.person_name||person?.full_name||person?.email||"บุคลากร";
  const m=document.createElement("div");m.className="modal-backdrop";
  m.innerHTML=`<div class="modal"><div class="modal-head"><div><h3>ยกเลิกการลงเวลา</h3><p>รายการจะถูกนำออกจากสถิติและ PDF แต่ระบบจะเก็บประวัติการยกเลิกไว้ตรวจสอบย้อนหลัง</p></div><button class="modal-close">×</button></div><div class="attendance-cancel-summary"><strong>${escapeHtml(name)}</strong><span>${officialAttendanceThaiDate(record.attendance_date)} · ${officialAttendanceTime(record.checkin_at,true)} น. · ${escapeHtml(officialAttendanceMethodLabel(record))}</span><small>${record.status==="late"?"สถานะเดิม: สาย":"สถานะเดิม: ตรงเวลา"}</small></div><div class="field"><label>เหตุผลการยกเลิก <span class="required">*</span></label><textarea class="input textarea" id="attendance-cancel-reason" maxlength="500" placeholder="เช่น กดลงเวลาโดยไม่ตั้งใจ / ทดสอบระบบ / บันทึกผิดรายการ"></textarea><span class="helper">หลังยกเลิก บุคลากรสามารถลงเวลาใหม่ในวันเดิมได้ หากระบบยังเปิดรับและผ่านเงื่อนไขของโหมดวันนั้น</span></div><div class="modal-actions"><button class="btn btn-ghost modal-cancel">ปิด</button><button class="btn btn-danger" id="attendance-cancel-confirm">ยืนยันยกเลิกการลงเวลา</button></div></div>`;
  document.body.appendChild(m);const close=()=>m.remove();m.querySelector(".modal-close").onclick=close;m.querySelector(".modal-cancel").onclick=close;
  m.querySelector("#attendance-cancel-confirm").onclick=async e=>{const reason=String(m.querySelector("#attendance-cancel-reason").value||"").trim();if(reason.length<3)return toast("กรุณาระบุเหตุผล","อย่างน้อย 3 ตัวอักษร เพื่อเก็บเป็นหลักฐานการแก้ไข","error");if(!window.confirm(`ยืนยันยกเลิกการลงเวลาของ ${name} ?`))return;buttonLoading(e.currentTarget,true,"กำลังยกเลิก...");const {error}=await supabase.rpc("cancel_official_attendance_record",{p_record_id:record.id,p_reason:reason});buttonLoading(e.currentTarget,false);if(error)return toast("ยกเลิกไม่สำเร็จ",error.message,"error");close();toast("ยกเลิกการลงเวลาแล้ว",`${name} สามารถลงเวลาใหม่ได้ หากระบบยังเปิดรับ` ,"success");await loadOfficialAttendanceWorkspace();await renderDashboard();};
}

function bindOfficialAttendanceEvents(){
  document.querySelector("#official-attendance-checkin")?.addEventListener("click",e=>officialAttendanceCheckIn(e.currentTarget));
  document.querySelector("#official-attendance-qr-scan")?.addEventListener("click",officialAttendanceQrScanModal);
  document.querySelector("#official-attendance-face-register")?.addEventListener("click",officialAttendanceFaceRegistrationModal);
  document.querySelector("#official-attendance-face-checkin")?.addEventListener("click",officialAttendanceFaceCheckInModal);
  document.querySelector("#official-attendance-face-delete")?.addEventListener("click",e=>officialAttendanceDeleteFaceRegistration(e.currentTarget));
  document.querySelector("#attendance-qr-rotate")?.addEventListener("click",e=>officialAttendanceRotateQr(e.currentTarget));
  document.querySelector("#attendance-face-manage")?.addEventListener("click",officialAttendanceFaceManagerModal);
  document.querySelector("#attendance-test-center")?.addEventListener("click",officialAttendanceTestCenterModal);
  document.querySelector("#attendance-retry-load")?.addEventListener("click",async e=>{buttonLoading(e.currentTarget,true,"กำลังโหลด...");state.officialAttendanceLoadError=null;await renderDashboard();});
  document.querySelector("#attendance-settings-open")?.addEventListener("click",officialAttendanceSettingsModal);
  document.querySelector("#attendance-day-setting-open")?.addEventListener("click",officialAttendanceDaySettingModal);
  document.querySelector("#attendance-duty-open")?.addEventListener("click",officialAttendanceDutyModal);
  document.querySelectorAll("[data-attendance-view]").forEach(b=>b.addEventListener("click",()=>{state.officialAttendanceView=b.dataset.attendanceView;renderDashboard();}));
  document.querySelector("#attendance-report-date")?.addEventListener("change",async e=>{state.officialAttendanceReportDate=e.currentTarget.value;const ay=officialAttendanceAcademicYearForDate(state.officialAttendanceReportDate);if(ay!==Number(state.officialAttendanceReportAcademicYear)){state.officialAttendanceReportAcademicYear=ay;await loadOfficialAttendanceWorkspace();}renderDashboard();});
  document.querySelector("#attendance-report-month")?.addEventListener("change",async e=>{state.officialAttendanceReportMonth=e.currentTarget.value;const ay=officialAttendanceAcademicYearForDate(`${e.currentTarget.value}-15`);if(ay!==Number(state.officialAttendanceReportAcademicYear)){state.officialAttendanceReportAcademicYear=ay;await loadOfficialAttendanceWorkspace();}renderDashboard();});
  document.querySelector("#attendance-report-year")?.addEventListener("change",async e=>{state.officialAttendanceReportAcademicYear=Number(e.currentTarget.value);await loadOfficialAttendanceWorkspace();renderDashboard();});
  document.querySelector("#attendance-report-semester")?.addEventListener("change",e=>{state.officialAttendanceReportSemester=Number(e.currentTarget.value);renderDashboard();});
  document.querySelector("#attendance-export-report")?.addEventListener("click",officialAttendanceExportCurrent);
  document.querySelectorAll("[data-attendance-cancel-record]").forEach(b=>b.addEventListener("click",()=>officialAttendanceCancelRecordModal(b.dataset.attendanceCancelRecord)));
  document.querySelectorAll("[data-attendance-duty-delete]").forEach(b=>b.addEventListener("click",async()=>{if(!window.confirm("ลบสถานะไปราชการรายการนี้?"))return;const {error}=await supabase.from("official_attendance_duty_records").delete().eq("id",b.dataset.attendanceDutyDelete);if(error)return toast("ลบไม่สำเร็จ",error.message,"error");await loadOfficialAttendanceWorkspace();await renderDashboard();}));
  officialAttendanceRenderQrCode();
}



// ===== Student Follow-up / ระบบติดตามนักเรียน (Build 11.0.29.3) =====
const STUDENT_FOLLOWUP_STATUS_LABEL={draft:"ฉบับร่าง",issued:"ออกหนังสือแล้ว",completed:"ติดตามครบแล้ว",cancelled:"ยกเลิก"};
function studentFollowupCanManageUi(){return isSuperAdminUser()||isAcademicHead();}
function studentFollowupCanCreateUi(){return !!state.user&&state.profile?.account_status==="active"&&!['director'].includes(state.profile?.role);}
function studentFollowupBatchById(id){return (state.studentFollowupBatches||[]).find(x=>x.id===id)||null;}
function studentFollowupCasesFor(batchId){return (state.studentFollowupCases||[]).filter(x=>x.batch_id===batchId).sort((a,b)=>String(a.class_label||'').localeCompare(String(b.class_label||''),'th')||Number(a.student_number||999)-Number(b.student_number||999)||String(a.student_name||'').localeCompare(String(b.student_name||''),'th'));}
function studentFollowupStatusLabel(v){return STUDENT_FOLLOWUP_STATUS_LABEL[v]||v||'—';}
function studentFollowupStatusClass(v){return v==='issued'?'active':v==='completed'?'success':v==='cancelled'?'rejected':'neutral';}
function studentFollowupToday(){return new Date().toLocaleDateString('en-CA');}
function studentFollowupMonthInput(dateValue){return String(dateValue||'').slice(0,7)||studentFollowupToday().slice(0,7);}
function studentFollowupMonthLabel(dateValue){return academicRegThaiDateParts(dateValue).month||'—';}
function studentFollowupThaiDate(dateValue){const p=academicRegThaiDateParts(dateValue);return p.day?`${p.day} ${p.month} ${p.year}`:'—';}
function studentFollowupDisplayDocNo(batch){return batch?.official_document_number?`ศธ ${academicRegThaiDigits(batch.official_document_number)}`:'ยังไม่ได้กำหนด';}
function studentFollowupCheckHtml(on){return `<span class="student-followup-check ${on?'checked':''}" aria-hidden="true"></span>`;}
function studentFollowupSettings(){return state.studentFollowupSettings||{};}
async function studentFollowupAssetDataUrl(url){const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error('โหลดทรัพยากรเอกสารไม่สำเร็จ');return blobToDataUrl(await r.blob());}
function studentFollowupCurrentYearOptions(){const base=Number(currentAcademicPeriod().academicYear||2569);return [base-1,base,base+1].map(y=>`<option value="${y}" ${String(state.studentFollowupAcademicYear)==String(y)?'selected':''}>${academicRegThaiDigits(y)}</option>`).join('');}
async function loadStudentFollowupWorkspace(){
  if(!state.studentFollowupAcademicYear)state.studentFollowupAcademicYear=currentAcademicPeriod().academicYear;
  if(!state.studentFollowupSemester)state.studentFollowupSemester=currentAcademicPeriod().semester;
  const year=String(state.studentFollowupAcademicYear),semester=Number(state.studentFollowupSemester);
  const [settingsRes,studentsRes,batchesRes]=await Promise.all([
    supabase.from('student_followup_settings').select('*').eq('id',1).maybeSingle(),
    supabase.rpc('get_student_followup_student_options',{p_academic_year:year,p_semester:semester}),
    supabase.from('student_followup_batches').select('*').eq('academic_year',year).eq('semester',semester).order('letter_date',{ascending:false}).order('created_at',{ascending:false})
  ]);
  if(settingsRes.error)console.warn('student followup settings',settingsRes.error);
  if(studentsRes.error)throw studentsRes.error;
  if(batchesRes.error)throw batchesRes.error;
  state.studentFollowupSettings=settingsRes.data||null;
  state.studentFollowupStudents=studentsRes.data||[];
  state.studentFollowupBatches=batchesRes.data||[];
  const ids=state.studentFollowupBatches.map(x=>x.id);
  if(ids.length){const casesRes=await supabase.from('student_followup_cases').select('*').in('batch_id',ids).order('created_at');if(casesRes.error)throw casesRes.error;state.studentFollowupCases=casesRes.data||[];}else state.studentFollowupCases=[];
}
function studentFollowupBatchRow(b){
  const cases=studentFollowupCasesFor(b.id),canEdit=b.status==='draft'&&(studentFollowupCanManageUi()||b.created_by===state.user?.id),canFollow=['issued','completed'].includes(b.status)&&(studentFollowupCanManageUi()||b.created_by===state.user?.id);
  return `<tr data-student-followup-row="${b.id}"><td><strong>${escapeHtml(b.batch_code||'—')}</strong><br><span class="table-muted">${studentFollowupThaiDate(b.letter_date)}</span></td><td><strong>${studentFollowupMonthLabel(b.absence_month)}</strong><br><span class="table-muted">ปีการศึกษา ${academicRegThaiDigits(b.academic_year)} · ภาคเรียนที่ ${academicRegThaiDigits(b.semester)}</span></td><td><strong>${escapeHtml(studentFollowupDisplayDocNo(b))}</strong><br><span class="table-muted">${cases.length} คน</span></td><td><span class="pill ${studentFollowupStatusClass(b.status)}">${studentFollowupStatusLabel(b.status)}</span></td><td><div class="admin-actions student-followup-row-actions"><button class="btn btn-ghost btn-small" data-student-followup-detail="${b.id}">รายละเอียด</button>${canEdit?`<button class="btn btn-ghost btn-small" data-student-followup-edit="${b.id}">แก้ไข</button>`:''}${studentFollowupCanManageUi()?`<button class="btn btn-ghost btn-small" data-student-followup-number="${b.id}">เลขที่ ศธ.</button>`:''}<button class="btn btn-secondary btn-small" data-student-followup-pdf="${b.id}">PDF</button>${b.status==='draft'&&studentFollowupCanManageUi()?`<button class="btn btn-primary btn-small" data-student-followup-issue="${b.id}">ออกหนังสือ</button>`:''}${canFollow&&cases.some(x=>x.followup_status!=='followed')?`<button class="btn btn-ghost btn-small" data-student-followup-detail="${b.id}">บันทึกติดตาม</button>`:''}</div></td></tr>`;
}
function studentFollowupWorkspaceHtml(){
  const batches=state.studentFollowupBatches||[],cases=state.studentFollowupCases||[],issued=batches.filter(x=>['issued','completed'].includes(x.status)).length,open=cases.filter(x=>x.followup_status!=='followed').length,canManage=studentFollowupCanManageUi();
  return `<section class="student-followup-page"><section class="student-followup-hero"><div><span class="eyebrow">กลุ่มงานบริหารวิชาการ · Student Follow-up</span><h2>ระบบติดตามนักเรียน</h2><p>จัดทำหนังสือแจ้งผู้ปกครองกรณีนักเรียนขาดเรียน เชื่อมรายชื่อนักเรียนกลาง และออกหนังสือราชการตามแบบโรงเรียน</p></div><div class="student-followup-hero-side"><span>หนังสือราชการ A4</span><strong>ตราครุฑ · เลขที่ ศธ. · TH Sarabun IT๙</strong><small>Build ${APP_BUILD}</small></div></section>
  <div class="stats-grid student-followup-stats"><article><span>ชุดหนังสือ</span><strong>${academicRegThaiDigits(batches.length)}</strong><small>ในช่วงที่เลือก</small></article><article><span>ออกหนังสือแล้ว</span><strong>${academicRegThaiDigits(issued)}</strong><small>ชุด</small></article><article><span>นักเรียนในรายการ</span><strong>${academicRegThaiDigits(cases.length)}</strong><small>คน</small></article><article><span>รอติดตามผล</span><strong>${academicRegThaiDigits(open)}</strong><small>คน</small></article></div>
  <section class="panel"><div class="panel-head"><div class="panel-title-wrap"><h3>ทะเบียนหนังสือติดตามนักเรียน</h3><p>เลือกปีการศึกษาและภาคเรียน แล้วสร้างหนังสือรายคนหรือออกเป็นชุดได้</p></div><div class="action-row">${canManage?`<button class="btn btn-ghost" id="student-followup-settings">ตั้งค่าเอกสาร</button>`:''}${studentFollowupCanCreateUi()?`<button class="btn btn-primary" id="student-followup-create">＋ สร้างชุดหนังสือ</button>`:''}</div></div>
  <div class="student-followup-toolbar"><div class="field"><label>ปีการศึกษา</label><select class="select" id="student-followup-year">${studentFollowupCurrentYearOptions()}</select></div><div class="field"><label>ภาคเรียน</label><select class="select" id="student-followup-semester"><option value="1" ${Number(state.studentFollowupSemester)===1?'selected':''}>๑</option><option value="2" ${Number(state.studentFollowupSemester)===2?'selected':''}>๒</option><option value="3" ${Number(state.studentFollowupSemester)===3?'selected':''}>๓</option></select></div><div class="field student-followup-search-field"><label>ค้นหา</label><input class="input" id="student-followup-search" value="${escapeHtml(state.studentFollowupSearch||'')}" placeholder="เลขชุด / เลขที่ ศธ. / ชื่อนักเรียน"></div></div>
  <div class="table-wrap"><table class="table student-followup-table"><thead><tr><th>ชุดหนังสือ / วันที่</th><th>เดือนที่ขาดเรียน</th><th>เลขที่ ศธ. / จำนวน</th><th>สถานะ</th><th>ดำเนินการ</th></tr></thead><tbody id="student-followup-list">${batches.length?batches.map(studentFollowupBatchRow).join(''):`<tr><td colspan="5"><div class="empty"><strong>ยังไม่มีหนังสือติดตามนักเรียน</strong><span>กด “สร้างชุดหนังสือ” เพื่อเริ่มรายการแรก</span></div></td></tr>`}</tbody></table></div></section></section>`;
}
function studentFollowupApplySearch(){
  const q=String(document.querySelector('#student-followup-search')?.value||'').trim().toLowerCase();state.studentFollowupSearch=q;
  document.querySelectorAll('[data-student-followup-row]').forEach(tr=>{const b=studentFollowupBatchById(tr.dataset.studentFollowupRow),hay=[b?.batch_code,b?.official_document_number,...studentFollowupCasesFor(b?.id).map(x=>x.student_name)].join(' ').toLowerCase();tr.hidden=!!q&&!hay.includes(q);});
}
function studentFollowupStudentRows(students,caseMap){return students.map(s=>{const c=caseMap.get(s.student_id),checked=!!c;return `<tr data-followup-student-row="${s.student_id}" data-followup-search="${escapeHtml(`${s.student_name} ${s.student_code} ${s.class_label} ${s.guardian_name||''}`.toLowerCase())}"><td><input type="checkbox" class="student-followup-pick" value="${s.student_id}" ${checked?'checked':''}></td><td><strong>${escapeHtml(s.student_name)}</strong><br><span class="table-muted">${escapeHtml(s.student_code||'—')}</span></td><td>${escapeHtml(s.class_label||'—')}<br><span class="table-muted">เลขที่ ${academicRegThaiDigits(s.student_number||'—')}</span></td><td>${escapeHtml(s.guardian_name||'ไม่พบข้อมูลผู้ปกครอง')}</td><td><input class="input student-followup-days" type="number" min="1" max="366" value="${c?.absence_total_days||10}" ${checked?'':'disabled'}></td><td><label class="student-followup-condition"><input type="checkbox" class="student-followup-over5" ${c?.over_five_consecutive?'checked':''} ${checked?'':'disabled'}> เกิน ๕ วันติดต่อกัน</label><label class="student-followup-condition"><input type="checkbox" class="student-followup-over7" ${c?.over_seven_in_month?'checked':''} ${checked?'':'disabled'}> เกิน ๗ วันติดต่อกัน ในรอบ ๑ เดือน</label></td><td><input class="input student-followup-note" value="${escapeHtml(c?.absence_note||'')}" placeholder="ถ้ามี" ${checked?'':'disabled'}></td></tr>`;}).join('');}
async function studentFollowupFormModal(batch=null){
  if(batch&&batch.status!=='draft')return toast('แก้ไขไม่ได้','ชุดหนังสือที่ออกแล้วจะล็อกข้อมูลต้นฉบับ','error');
  const students=state.studentFollowupStudents||[];if(!students.length)return toast('ไม่พบรายชื่อนักเรียน','ตรวจสอบปีการศึกษาและภาคเรียนในระบบบัญชีรายชื่อนักเรียน','error');
  const caseMap=new Map((batch?studentFollowupCasesFor(batch.id):[]).map(x=>[x.student_id,x])),month=studentFollowupMonthInput(batch?.absence_month),letterDate=batch?.letter_date||studentFollowupToday();
  const m=document.createElement('div');m.className='modal-backdrop';m.innerHTML=`<div class="modal modal-extra-wide student-followup-form-modal"><div class="modal-head"><div><h3>${batch?'แก้ไข':'สร้าง'}ชุดหนังสือติดตามนักเรียน</h3><p>ปีการศึกษา ${academicRegThaiDigits(state.studentFollowupAcademicYear)} · ภาคเรียนที่ ${academicRegThaiDigits(state.studentFollowupSemester)} · เลือกนักเรียนได้หลายคนในหนังสือเลขเดียวกัน</p></div><button class="modal-close">×</button></div><form id="student-followup-form" class="form-grid"><section class="student-followup-form-section"><h4>ข้อมูลหนังสือ</h4><div class="form-row"><div class="field"><label>เดือนที่นักเรียนขาดเรียน</label><input class="input" type="month" name="absence_month" value="${escapeHtml(month)}" required></div><div class="field"><label>วันที่ออกหนังสือ</label><input class="input" type="date" name="letter_date" value="${escapeHtml(letterDate)}" required></div></div><span class="helper">เลขที่ ศธ. กำหนดภายหลังจากหน้ารายการ เพื่อให้ผู้มีสิทธิ์งานวิชาการเป็นผู้ควบคุมเลขหนังสือ</span></section><section class="student-followup-form-section"><div class="panel-head"><div><h4>เลือกรายชื่อนักเรียน</h4><p>กรอกจำนวนวันที่ขาดและเลือกเงื่อนไขอย่างน้อย 1 ข้อสำหรับแต่ละคน</p></div><input class="input student-followup-student-search" id="student-followup-student-search" placeholder="ค้นหาชื่อ / ชั้น / เลขประจำตัว"></div><div class="table-wrap student-followup-pick-wrap"><table class="table student-followup-pick-table"><thead><tr><th></th><th>นักเรียน</th><th>ชั้น</th><th>ผู้ปกครอง</th><th>รวม (วัน)</th><th>เงื่อนไข</th><th>หมายเหตุ</th></tr></thead><tbody>${studentFollowupStudentRows(students,caseMap)}</tbody></table></div></section></form><div class="modal-actions"><button class="btn btn-ghost modal-cancel">ยกเลิก</button><button class="btn btn-primary" id="student-followup-save">บันทึกฉบับร่าง</button></div></div>`;document.body.appendChild(m);const close=()=>m.remove();m.querySelector('.modal-close').onclick=close;m.querySelector('.modal-cancel').onclick=close;
  const toggleRow=cb=>{const tr=cb.closest('tr');tr.querySelectorAll('.student-followup-days,.student-followup-over5,.student-followup-over7,.student-followup-note').forEach(el=>el.disabled=!cb.checked);if(cb.checked&&!tr.querySelector('.student-followup-over5').checked&&!tr.querySelector('.student-followup-over7').checked)tr.querySelector('.student-followup-over5').checked=true;};m.querySelectorAll('.student-followup-pick').forEach(cb=>{toggleRow(cb);cb.onchange=()=>toggleRow(cb);});
  m.querySelector('#student-followup-student-search').oninput=e=>{const q=e.currentTarget.value.trim().toLowerCase();m.querySelectorAll('[data-followup-student-row]').forEach(tr=>tr.hidden=!!q&&!tr.dataset.followupSearch.includes(q));};
  m.querySelector('#student-followup-save').onclick=async e=>{const form=m.querySelector('#student-followup-form');if(!form.reportValidity())return;const selected=[...m.querySelectorAll('.student-followup-pick:checked')];if(!selected.length)return toast('ยังไม่ได้เลือกนักเรียน','เลือกอย่างน้อย 1 คน','error');const items=[];for(const cb of selected){const tr=cb.closest('tr'),over5=tr.querySelector('.student-followup-over5').checked,over7=tr.querySelector('.student-followup-over7').checked;if(!over5&&!over7)return toast('เงื่อนไขยังไม่ครบ',`${students.find(x=>x.student_id===cb.value)?.student_name||'นักเรียน'} ต้องเลือกอย่างน้อย 1 เงื่อนไข`,'error');items.push({student_id:cb.value,absence_total_days:Number(tr.querySelector('.student-followup-days').value||0),over_five_consecutive:over5,over_seven_in_month:over7,absence_note:tr.querySelector('.student-followup-note').value.trim()||null});}const fd=new FormData(form),payload={academic_year:String(state.studentFollowupAcademicYear),semester:Number(state.studentFollowupSemester),absence_month:`${fd.get('absence_month')}-01`,letter_date:String(fd.get('letter_date'))};buttonLoading(e.currentTarget,true,'กำลังบันทึก...');try{let id=batch?.id;if(id){const up=await supabase.from('student_followup_batches').update({absence_month:payload.absence_month,letter_date:payload.letter_date}).eq('id',id);if(up.error)throw up.error;const del=await supabase.from('student_followup_cases').delete().eq('batch_id',id);if(del.error)throw del.error;}else{const ins=await supabase.from('student_followup_batches').insert({...payload,status:'draft'}).select('id,batch_code').single();if(ins.error)throw ins.error;id=ins.data.id;}const add=await supabase.rpc('add_student_followup_cases',{p_batch_id:id,p_items:items});if(add.error)throw add.error;close();toast('บันทึกชุดหนังสือแล้ว',`${items.length} คน · สามารถกำหนดเลขที่ ศธ. และ Preview PDF ได้ทันที`,'success');await loadStudentFollowupWorkspace();await renderDashboard();}catch(err){toast('บันทึกไม่สำเร็จ',err.message||String(err),'error');}finally{buttonLoading(e.currentTarget,false);}};
}
async function studentFollowupNumberModal(batch){
  if(!studentFollowupCanManageUi())return;let history=[];try{const h=await supabase.rpc('get_student_followup_official_number_history',{p_batch_id:batch.id});if(!h.error)history=h.data||[];}catch(_){}
  const m=document.createElement('div');m.className='modal-backdrop';m.innerHTML=`<div class="modal"><div class="modal-head"><div><h3>กำหนดเลขที่ ศธ.</h3><p>${escapeHtml(batch.batch_code)} · ใช้เลขเดียวกันกับนักเรียนทุกคนในชุดนี้</p></div><button class="modal-close">×</button></div><div class="field"><label>เลขที่หนังสือหลังคำว่า “ศธ”</label><div class="student-followup-number-input"><strong>ที่ ศธ</strong><input class="input" id="student-followup-document-number" value="${escapeHtml(batch.official_document_number||'')}" placeholder="เช่น 04049.196/ว235"></div><span class="helper">กรอกเฉพาะเลขหลัง “ศธ” ระบบจะเติมคำว่า “ที่ ศธ” ใน PDF ให้อัตโนมัติ</span></div>${history.length?`<div class="student-followup-number-history"><strong>ประวัติการแก้เลข</strong>${history.slice(0,8).map(h=>`<div><span>${escapeHtml(h.previous_number||'—')} → ${escapeHtml(h.new_number||'—')}</span><small>${escapeHtml(h.changed_by_name||'')} · ${formatDate(h.changed_at)}</small></div>`).join('')}</div>`:''}<div class="modal-actions"><button class="btn btn-ghost modal-cancel">ปิด</button><button class="btn btn-primary" id="student-followup-number-save">บันทึกเลขที่ ศธ.</button></div></div>`;document.body.appendChild(m);const close=()=>m.remove();m.querySelector('.modal-close').onclick=close;m.querySelector('.modal-cancel').onclick=close;m.querySelector('#student-followup-number-save').onclick=async e=>{buttonLoading(e.currentTarget,true,'กำลังบันทึก...');const {error}=await supabase.rpc('set_student_followup_official_number',{p_batch_id:batch.id,p_document_number:m.querySelector('#student-followup-document-number').value.trim()||null});buttonLoading(e.currentTarget,false);if(error)return toast('บันทึกเลขที่ ศธ. ไม่สำเร็จ',error.message,'error');close();toast('บันทึกเลขที่ ศธ. แล้ว','เลขจะถูกใช้กับหนังสือทุกหน้าของชุดนี้','success');await loadStudentFollowupWorkspace();await renderDashboard();};
}
async function studentFollowupIssue(batch){if(!studentFollowupCanManageUi())return;const cases=studentFollowupCasesFor(batch.id);if(!batch.official_document_number)return studentFollowupNumberModal(batch);if(!cases.length)return toast('ยังไม่มีนักเรียนในชุดหนังสือ','','error');if(!confirm(`ยืนยันออกหนังสือเลขที่ ศธ ${batch.official_document_number} จำนวน ${cases.length} ฉบับ?\n\nหลังออกหนังสือแล้ว รายชื่อนักเรียนและข้อมูลการขาดเรียนจะล็อกเพื่อรักษาหลักฐานเอกสาร`))return;const {error}=await supabase.rpc('issue_student_followup_batch',{p_batch_id:batch.id});if(error)return toast('ออกหนังสือไม่สำเร็จ',error.message,'error');toast('ออกหนังสือแล้ว',`เลขที่ ศธ ${batch.official_document_number} · ${cases.length} ฉบับ`,'success');await loadStudentFollowupWorkspace();await renderDashboard();}
function studentFollowupFollowModal(c){const m=document.createElement('div');m.className='modal-backdrop';m.innerHTML=`<div class="modal"><div class="modal-head"><div><h3>บันทึกผลการติดตาม</h3><p>${escapeHtml(c.student_name)} · ${escapeHtml(c.class_label)}</p></div><button class="modal-close">×</button></div><div class="field"><label>ผล / หมายเหตุการติดตาม</label><textarea class="input textarea" id="student-followup-result" placeholder="เช่น ติดต่อผู้ปกครองแล้ว / นักเรียนกลับมาเรียนตามปกติ">${escapeHtml(c.followup_note||'')}</textarea></div><div class="modal-actions"><button class="btn btn-ghost modal-cancel">ปิด</button><button class="btn btn-primary" id="student-followup-result-save">บันทึกว่าติดตามแล้ว</button></div></div>`;document.body.appendChild(m);const close=()=>m.remove();m.querySelector('.modal-close').onclick=close;m.querySelector('.modal-cancel').onclick=close;m.querySelector('#student-followup-result-save').onclick=async e=>{buttonLoading(e.currentTarget,true,'กำลังบันทึก...');const {error}=await supabase.rpc('mark_student_followup_case_followed',{p_case_id:c.id,p_note:m.querySelector('#student-followup-result').value.trim()||null});buttonLoading(e.currentTarget,false);if(error)return toast('บันทึกผลติดตามไม่สำเร็จ',error.message,'error');close();toast('บันทึกผลติดตามแล้ว',c.student_name,'success');await loadStudentFollowupWorkspace();await renderDashboard();};}
function studentFollowupDetailModal(batch){const cases=studentFollowupCasesFor(batch.id),canFollow=['issued','completed'].includes(batch.status)&&(studentFollowupCanManageUi()||batch.created_by===state.user?.id);const m=document.createElement('div');m.className='modal-backdrop';m.innerHTML=`<div class="modal modal-extra-wide"><div class="modal-head"><div><h3>รายละเอียดชุดหนังสือติดตาม</h3><p>${escapeHtml(batch.batch_code)} · ${escapeHtml(studentFollowupDisplayDocNo(batch))} · ${studentFollowupThaiDate(batch.letter_date)}</p></div><button class="modal-close">×</button></div><div class="student-followup-detail-summary"><article><span>เดือนที่ขาดเรียน</span><strong>${studentFollowupMonthLabel(batch.absence_month)}</strong></article><article><span>จำนวนนักเรียน</span><strong>${academicRegThaiDigits(cases.length)} คน</strong></article><article><span>สถานะ</span><strong>${studentFollowupStatusLabel(batch.status)}</strong></article><article><span>ผู้ลงนาม</span><strong>${escapeHtml(batch.director_name_snapshot||'จะกำหนดเมื่อออกหนังสือ')}</strong></article></div><div class="table-wrap"><table class="table"><thead><tr><th>นักเรียน</th><th>ชั้น</th><th>ผู้ปกครอง</th><th>ขาดเรียน</th><th>เงื่อนไข</th><th>ติดตาม</th><th>PDF</th></tr></thead><tbody>${cases.map(c=>`<tr><td><strong>${escapeHtml(c.student_name)}</strong><br><span class="table-muted">${escapeHtml(c.student_code)}</span></td><td>${escapeHtml(c.class_label)}</td><td>${escapeHtml(c.guardian_name||'ผู้ปกครอง')}</td><td>${academicRegThaiDigits(c.absence_total_days)} วัน</td><td>${c.over_five_consecutive?'✓ เกิน ๕ วันติดต่อกัน':''}${c.over_five_consecutive&&c.over_seven_in_month?'<br>':''}${c.over_seven_in_month?'✓ เกิน ๗ วันติดต่อกัน ในรอบ ๑ เดือน':''}</td><td>${c.followup_status==='followed'?`<span class="pill success">ติดตามแล้ว</span>${c.followup_note?`<br><span class="table-muted">${escapeHtml(c.followup_note)}</span>`:''}`:canFollow?`<button class="btn btn-ghost btn-small" data-student-followup-follow="${c.id}">บันทึกผล</button>`:'รอติดตาม'}</td><td><button class="btn btn-secondary btn-small" data-student-followup-case-pdf="${c.id}">PDF รายคน</button></td></tr>`).join('')}</tbody></table></div><div class="modal-actions"><button class="btn btn-ghost modal-cancel">ปิด</button><button class="btn btn-primary" id="student-followup-batch-pdf">Preview PDF ทั้งชุด</button></div></div>`;document.body.appendChild(m);const close=()=>m.remove();m.querySelector('.modal-close').onclick=close;m.querySelector('.modal-cancel').onclick=close;m.querySelector('#student-followup-batch-pdf').onclick=async e=>{buttonLoading(e.currentTarget,true,'กำลังสร้าง...');await studentFollowupOpenPdf(batch,cases);buttonLoading(e.currentTarget,false);};m.querySelectorAll('[data-student-followup-case-pdf]').forEach(b=>b.onclick=async()=>{const c=cases.find(x=>x.id===b.dataset.studentFollowupCasePdf);if(c)await studentFollowupOpenPdf(batch,[c]);});m.querySelectorAll('[data-student-followup-follow]').forEach(b=>b.onclick=()=>{const c=cases.find(x=>x.id===b.dataset.studentFollowupFollow);if(c){close();studentFollowupFollowModal(c);}});}
function studentFollowupSettingsModal(){if(!studentFollowupCanManageUi())return;const s=studentFollowupSettings(),m=document.createElement('div');m.className='modal-backdrop';m.innerHTML=`<div class="modal"><div class="modal-head"><div><h3>ตั้งค่าหนังสือติดตามนักเรียน</h3><p>ข้อมูลหัว/ท้ายของแบบหนังสือราชการ · ผู้ลงนามใช้ผู้บริหารที่กำหนดในระบบกลางเดียวกับใบย้ายโดยอัตโนมัติ</p></div><button class="modal-close">×</button></div><form id="student-followup-settings-form" class="form-grid"><div class="student-followup-central-signer-note"><strong>ผู้ลงนาม</strong><span>ใช้ชื่อผู้อำนวยการและตำแหน่งจากการตั้งค่าผู้บริหาร/งานทะเบียนกลาง ไม่ล็อกชื่อบุคคลไว้ในระบบติดตามนักเรียน</span></div><div class="field"><label>ที่อยู่ส่วนหัวหนังสือ</label><textarea class="input textarea" name="official_school_address_text">${escapeHtml(s.official_school_address_text||'')}</textarea></div><div class="form-row"><div class="field"><label>โทร</label><input class="input" name="official_phone_text" value="${escapeHtml(s.official_phone_text||'')}"></div><div class="field"><label>อีเมล</label><input class="input" name="official_email_text" value="${escapeHtml(s.official_email_text||'')}"></div></div><div class="field"><label>คำขวัญบรรทัดที่ 1</label><input class="input" name="motto_line_1" value="${escapeHtml(s.motto_line_1||'')}"></div><div class="field"><label>คำขวัญบรรทัดที่ 2</label><input class="input" name="motto_line_2" value="${escapeHtml(s.motto_line_2||'')}"></div><div class="field"><label>คำขวัญบรรทัดที่ 3</label><textarea class="input textarea" name="motto_line_3">${escapeHtml(s.motto_line_3||'')}</textarea></div><div class="modal-actions"><button type="button" class="btn btn-ghost modal-cancel">ยกเลิก</button><button class="btn btn-primary" type="submit">บันทึกการตั้งค่า</button></div></form></div>`;document.body.appendChild(m);const close=()=>m.remove();m.querySelector('.modal-close').onclick=close;m.querySelector('.modal-cancel').onclick=close;m.querySelector('#student-followup-settings-form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),btn=e.submitter;buttonLoading(btn,true,'กำลังบันทึก...');const payload=Object.fromEntries(['official_school_address_text','official_phone_text','official_email_text','motto_line_1','motto_line_2','motto_line_3'].map(k=>[k,String(fd.get(k)||'').trim()]));const {error}=await supabase.from('student_followup_settings').update({...payload,updated_by:state.user.id}).eq('id',1);buttonLoading(btn,false);if(error)return toast('บันทึกการตั้งค่าไม่สำเร็จ',error.message,'error');close();toast('บันทึกการตั้งค่าแล้ว','เอกสาร PDF ใหม่จะใช้ข้อมูลชุดนี้','success');await loadStudentFollowupWorkspace();await renderDashboard();};}
async function studentFollowupSignatureData(batch){if(batch?.director_signature_id)return storedSignatureDataUrl(batch.director_signature_id);if(batch?.director_signature_path){const dl=await supabase.storage.from(batch.director_signature_bucket||'signatures').download(batch.director_signature_path);if(!dl.error)return blobToDataUrl(dl.data);}return null;}
async function studentFollowupCurrentDirector(){
  const signers=await academicTransferPdfSigners();
  const director=signers?.director||{};
  return {
    user_id:director.user_id||director.id||null,
    full_name:String(director.full_name||'').trim(),
    position:String(state.academicRegistrationSettings?.official_director_position_text||studentFollowupSettings().director_position_text||`ผู้อำนวยการ${schoolName()}`).trim()
  };
}
function studentFollowupPdfPageHtml(batch,c,garuda,signature,director){
  const s=studentFollowupSettings(),date=academicRegThaiDateParts(batch.letter_date),month=studentFollowupMonthLabel(batch.absence_month),doc=batch.official_document_number?academicRegThaiDigits(batch.official_document_number):'........................................',addrHtml=academicRegOfficialSchoolAddressHtml(s.official_school_address_text||schoolAddress()),signer=director?.full_name||'........................................................',position=director?.position||`ผู้อำนวยการ${schoolName()}`;
  const phone=String(s.official_phone_text||'').trim(),email=String(s.official_email_text||'').trim();
  const motto=[s.motto_line_1,s.motto_line_2,s.motto_line_3].map(x=>String(x||'').trim()).filter(Boolean);
  return `<article class="student-followup-pdf-page academic-transfer-official-document">
    <div class="official-transfer-content">
      <header class="official-transfer-header"><img src="${garuda}" alt="ตราครุฑ"></header>
      <div class="official-transfer-topline">
        <div class="official-transfer-number">ที่ ศธ. ${escapeHtml(doc)}</div>
        <div class="official-transfer-address">${addrHtml}</div>
      </div>
      <div class="official-transfer-date official-garuda-date-start">${date.day} ${date.month} ${date.year}</div>
      <div class="official-transfer-meta">
        <div><b>เรื่อง</b><span>นักเรียนขาดเรียน</span></div>
        <div><b>เรียน</b><span>ผู้ปกครอง ${escapeHtml(c.student_name)}</span></div>
      </div>
      <div class="official-transfer-body student-followup-shared-body">
        <p>ด้วย ${escapeHtml(c.student_name)} ซึ่งอยู่ในความปกครองของท่านหยุดเรียนมาแล้วในเดือน ${escapeHtml(month)} รวม ${academicRegThaiDigits(c.absence_total_days)} วัน ${studentFollowupCheckHtml(c.over_five_consecutive)} เกินห้าวันติดต่อกัน ${studentFollowupCheckHtml(c.over_seven_in_month)} เกินเจ็ดวันติดต่อกัน ในรอบ ๑ เดือน โดยไม่ได้รับอนุญาต และไม่แจ้งสาเหตุให้โรงเรียนทราบ ซึ่งก่อให้เกิดผลเสียต่อการเรียนของนักเรียนเป็นอย่างยิ่ง โรงเรียนจึงขอเตือนท่านส่งนักเรียนเข้าเรียนตามปกติโดยด่วน หากฝ่าฝืนโดยปราศจากเหตุผล อันสมควร จะมีความผิดตามมาตรา ๑๕ แห่งพระราชบัญญัติการศึกษาภาคบังคับ พ.ศ. ๒๕๔๕ ต้องระวางโทษปรับไม่เกิน ๑๐,๐๐๐ บาท (หนึ่งหมื่นบาทถ้วน)</p>
        <p>จึงเรียนมาเพื่อทราบและดำเนินการต่อไป</p>
      </div>
      <div class="official-transfer-signoff">
        <div>ขอแสดงความนับถือ</div>
        <div class="official-transfer-sign-space student-followup-shared-sign-space">${signature?`<img class="student-followup-shared-signature-img" src="${signature}" alt="ลายเซ็น">`:''}</div>
        <div>( ${escapeHtml(signer)} )</div>
        <div>${escapeHtml(position)}</div>
      </div>
      <div class="official-transfer-footer student-followup-shared-footer">
        <div>${escapeHtml(schoolName())}</div>
        ${phone?`<div>โทร. ${escapeHtml(academicRegThaiDigits(phone))}</div>`:''}
        ${email?`<div>ไปรษณีอิเล็กทรอนิกส์ : ${escapeHtml(email)}</div>`:''}
      </div>
    </div>
    ${motto.length?`<div class="student-followup-shared-motto">${motto.map(x=>`<strong>${escapeHtml(x)}</strong>`).join('')}</div>`:''}
  </article>`;
}
async function studentFollowupBuildPdf(batch,cases){
  if(!batch||!cases?.length)throw new Error('ไม่มีรายการสำหรับสร้าง PDF');
  await ensureOfficialPdfFont('16pt');
  const [garuda,currentDirector,snapshotSignature]=await Promise.all([studentFollowupAssetDataUrl('./garuda-official.png'),studentFollowupCurrentDirector(),studentFollowupSignatureData(batch)]);
  const snapshotName=String(batch?.director_name_snapshot||'').trim();
  const signature=snapshotSignature&&(!snapshotName||!currentDirector.full_name||snapshotName===currentDirector.full_name)?snapshotSignature:null;
  const host=document.createElement('div');
  host.className='student-followup-pdf-host';
  host.innerHTML=cases.map(c=>studentFollowupPdfPageHtml(batch,c,garuda,signature,currentDirector)).join('');
  document.body.appendChild(host);
  try{
    await Promise.all([...host.querySelectorAll('img')].map(img=>img.complete?Promise.resolve():new Promise(r=>{img.onload=img.onerror=r;})));
    await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
    const pages=[...host.querySelectorAll('.student-followup-pdf-page')];
    pages.forEach(page=>{
      const content=page.querySelector('.official-transfer-content');
      if(content)officialAlignAddressStartToDateEnd(content,'.official-transfer-address','.official-transfer-date');
      academicTransferFitOfficialToOnePage(page);
      void page.offsetHeight;
    });
    await new Promise(r=>requestAnimationFrame(r));
    const pdf=new jsPDF({orientation:'portrait',unit:'mm',format:'a4',compress:true});
    for(let i=0;i<pages.length;i++){
      if(i)pdf.addPage('a4','portrait');
      const canvas=await html2canvas(pages[i],{scale:2.5,useCORS:true,backgroundColor:'#fff',logging:false});
      pdf.addImage(canvas.toDataURL('image/jpeg',.98),'JPEG',0,0,210,297,undefined,'FAST');
    }
    const one=cases.length===1;
    return {blob:pdf.output('blob'),filename:one?`หนังสือติดตาม_${academicRegSafeFileBase(cases[0].student_name)}_${academicRegSafeFileBase(batch.batch_code)}.pdf`:`หนังสือติดตามนักเรียน_${academicRegSafeFileBase(batch.batch_code)}_${cases.length}คน.pdf`};
  }finally{host.remove();}
}
async function studentFollowupOpenPdf(batch,cases=studentFollowupCasesFor(batch.id)){try{const built=await studentFollowupBuildPdf(batch,cases);openPdfPreviewModal({title:cases.length===1?'หนังสือติดตามนักเรียน — รายคน':'หนังสือติดตามนักเรียน — ทั้งชุด',subtitle:`${batch.batch_code} · ${cases.length} ฉบับ · ${studentFollowupDisplayDocNo(batch)}`,blob:built.blob,filename:built.filename});}catch(err){console.error(err);toast('สร้าง PDF ไม่สำเร็จ',err.message||String(err),'error');}}
async function studentFollowupDelete(batch){if(batch.status!=='draft')return;if(!confirm(`ยืนยันลบ ${batch.batch_code} ?`))return;const {error}=await supabase.from('student_followup_batches').delete().eq('id',batch.id);if(error)return toast('ลบไม่สำเร็จ',error.message,'error');toast('ลบฉบับร่างแล้ว','','success');await loadStudentFollowupWorkspace();await renderDashboard();}
function bindStudentFollowupEvents(){document.querySelector('#student-followup-year')?.addEventListener('change',async e=>{state.studentFollowupAcademicYear=Number(e.currentTarget.value);await loadStudentFollowupWorkspace();renderDashboard();});document.querySelector('#student-followup-semester')?.addEventListener('change',async e=>{state.studentFollowupSemester=Number(e.currentTarget.value);await loadStudentFollowupWorkspace();renderDashboard();});document.querySelector('#student-followup-search')?.addEventListener('input',studentFollowupApplySearch);document.querySelector('#student-followup-create')?.addEventListener('click',()=>studentFollowupFormModal());document.querySelector('#student-followup-settings')?.addEventListener('click',studentFollowupSettingsModal);document.querySelectorAll('[data-student-followup-detail]').forEach(b=>b.addEventListener('click',()=>studentFollowupDetailModal(studentFollowupBatchById(b.dataset.studentFollowupDetail))));document.querySelectorAll('[data-student-followup-edit]').forEach(b=>b.addEventListener('click',()=>studentFollowupFormModal(studentFollowupBatchById(b.dataset.studentFollowupEdit))));document.querySelectorAll('[data-student-followup-number]').forEach(b=>b.addEventListener('click',()=>studentFollowupNumberModal(studentFollowupBatchById(b.dataset.studentFollowupNumber))));document.querySelectorAll('[data-student-followup-pdf]').forEach(b=>b.addEventListener('click',()=>studentFollowupOpenPdf(studentFollowupBatchById(b.dataset.studentFollowupPdf))));document.querySelectorAll('[data-student-followup-issue]').forEach(b=>b.addEventListener('click',()=>studentFollowupIssue(studentFollowupBatchById(b.dataset.studentFollowupIssue))));studentFollowupApplySearch();}


